fn key_character(key: Key, modifiers: egui::Modifiers) -> Option<char> {
    if modifiers.ctrl || modifiers.alt || modifiers.command || modifiers.mac_cmd {
        return None;
    }
    let letter = match key {
        Key::A => 'a',
        Key::B => 'b',
        Key::C => 'c',
        Key::D => 'd',
        Key::E => 'e',
        Key::F => 'f',
        Key::G => 'g',
        Key::H => 'h',
        Key::I => 'i',
        Key::J => 'j',
        Key::K => 'k',
        Key::L => 'l',
        Key::M => 'm',
        Key::N => 'n',
        Key::O => 'o',
        Key::P => 'p',
        Key::Q => 'q',
        Key::R => 'r',
        Key::S => 's',
        Key::T => 't',
        Key::U => 'u',
        Key::V => 'v',
        Key::W => 'w',
        Key::X => 'x',
        Key::Y => 'y',
        Key::Z => 'z',
        _ => '\0',
    };
    if letter != '\0' {
        return Some(if modifiers.shift {
            letter.to_ascii_uppercase()
        } else {
            letter
        });
    }
    Some(match (key, modifiers.shift) {
        (Key::Space, _) => ' ',
        (Key::Quote, false) => '\'',
        (Key::Quote, true) => '"',
        (Key::Comma, false) => ',',
        (Key::Comma, true) => '<',
        (Key::Period, false) => '.',
        (Key::Period, true) => '>',
        (Key::Slash, false) => '/',
        (Key::Slash, true) => '?',
        (Key::OpenBracket, false) => '[',
        (Key::OpenBracket, true) => '{',
        (Key::CloseBracket, false) => ']',
        (Key::CloseBracket, true) => '}',
        (Key::Minus, false) => '-',
        (Key::Minus, true) => '_',
        (Key::Equals, false) => '=',
        (Key::Equals, true) => '+',
        (Key::Semicolon, false) => ';',
        (Key::Semicolon, true) => ':',
        (Key::Backslash, false) => '\\',
        (Key::Backslash, true) => '|',
        (Key::Backtick, false) => '`',
        (Key::Backtick, true) => '~',
        (Key::Num0, false) => '0',
        (Key::Num1, false) => '1',
        (Key::Num2, false) => '2',
        (Key::Num3, false) => '3',
        (Key::Num4, false) => '4',
        (Key::Num5, false) => '5',
        (Key::Num6, false) => '6',
        (Key::Num7, false) => '7',
        (Key::Num8, false) => '8',
        (Key::Num9, false) => '9',
        (Key::Num1, true) => '!',
        (Key::Num3, true) => '#',
        (Key::Num4, true) => '$',
        (Key::Num5, true) => '%',
        (Key::Num6, true) => '^',
        (Key::Num7, true) => '&',
        (Key::Num8, true) => '*',
        (Key::Num9, true) => '(',
        (Key::Num0, true) => ')',
        (Key::Colon, _) => ':',
        (Key::Questionmark, _) => '?',
        (Key::OpenCurlyBracket, _) => '{',
        (Key::CloseCurlyBracket, _) => '}',
        (Key::Plus, _) => '+',
        (Key::Pipe, _) => '|',
        (Key::Exclamationmark, _) => '!',
        _ => return None,
    })
}

fn text_scope_owns_printable(scopes: &[Scope], behavior: KeybindingBehavior) -> bool {
    if scopes.iter().any(|scope| {
        matches!(
            scope,
            Scope::VimNormal | Scope::VimVisual | Scope::VimOperator
        )
    }) {
        return false;
    }
    scopes.iter().any(|scope| {
        matches!(
            scope,
            Scope::VimInsert
                | Scope::VimReplace
                | Scope::Find
                | Scope::ProjectSearch
                | Scope::Agent
                | Scope::Terminal
                | Scope::Settings
        ) || (*scope == Scope::DocumentEditor && behavior == KeybindingBehavior::Standard)
    })
}

fn primary_modifiers() -> egui::Modifiers {
    if KeybindingPlatform::current() == KeybindingPlatform::Macos {
        egui::Modifiers {
            mac_cmd: true,
            command: true,
            ..egui::Modifiers::NONE
        }
    } else {
        egui::Modifiers {
            ctrl: true,
            command: true,
            ..egui::Modifiers::NONE
        }
    }
}
pub(crate) fn resize_divider_stroke(ctx: &egui::Context, active: bool) -> egui::Stroke {
    egui::Stroke::new(
        ctx.input(|input| input.physical_pixel_size()),
        if active {
            theme::accent()
        } else {
            theme::border::strong_color()
        },
    )
}

