fn agent_near_bottom(offset: f32, max_offset: f32) -> bool {
    max_offset - offset <= AGENT_FOLLOW_THRESHOLD
}

fn agent_transcript_fade_mesh(rect: egui::Rect, opaque: Color32) -> egui::Mesh {
    let mut mesh = egui::Mesh::default();
    let height = AGENT_TRANSCRIPT_EDGE_FADE.min(rect.height() * 0.5);
    for (position, color) in [
        (rect.left_top(), opaque),
        (rect.right_top(), opaque),
        (
            egui::pos2(rect.left(), rect.top() + height),
            Color32::TRANSPARENT,
        ),
        (
            egui::pos2(rect.right(), rect.top() + height),
            Color32::TRANSPARENT,
        ),
        (
            egui::pos2(rect.left(), rect.bottom() - height),
            Color32::TRANSPARENT,
        ),
        (
            egui::pos2(rect.right(), rect.bottom() - height),
            Color32::TRANSPARENT,
        ),
        (rect.left_bottom(), opaque),
        (rect.right_bottom(), opaque),
    ] {
        mesh.colored_vertex(position, color);
    }
    mesh.indices
        .extend_from_slice(&[0, 1, 2, 2, 1, 3, 4, 5, 6, 6, 5, 7]);
    mesh
}

fn draw_agent_content(
    ui: &mut egui::Ui,
    content: &DisplayContent,
    search: Option<(&str, Option<usize>)>,
) {
    match content {
        DisplayContent::Image {
            mime_type,
            uri,
            encoded_bytes,
        } => {
            agent_search_label(
                ui,
                &format!("Image · {mime_type} · {encoded_bytes} encoded bytes"),
                theme::typography::body(),
                theme::text().primary,
                search,
            );
            if let Some(uri) = uri {
                agent_search_label(
                    ui,
                    uri,
                    theme::typography::code_small(),
                    theme::text().primary,
                    search,
                );
            }
        }
        DisplayContent::Audio {
            mime_type,
            encoded_bytes,
        } => {
            agent_search_label(
                ui,
                &format!("Audio · {mime_type} · {encoded_bytes} encoded bytes"),
                theme::typography::body(),
                theme::text().primary,
                search,
            );
        }
        DisplayContent::ResourceLink {
            name,
            title,
            uri,
            description,
            mime_type,
            size,
        } => {
            agent_search_label(
                ui,
                title.as_deref().unwrap_or(name),
                theme::typography::body(),
                theme::text().primary,
                search,
            );
            agent_search_label(
                ui,
                uri,
                theme::typography::code_small(),
                theme::text().primary,
                search,
            );
            if let Some(description) = description {
                agent_search_label(
                    ui,
                    description,
                    theme::typography::body(),
                    theme::text().primary,
                    search,
                );
            }
            let metadata = [mime_type.clone(), size.map(|size| format!("{size} bytes"))]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" · ");
            if !metadata.is_empty() {
                agent_search_label(
                    ui,
                    &metadata,
                    theme::typography::small(),
                    theme::text().muted,
                    search,
                );
            }
        }
        DisplayContent::TextResource {
            uri,
            mime_type,
            text,
        } => {
            agent_search_label(
                ui,
                mime_type.as_deref().unwrap_or("Text resource"),
                theme::typography::body(),
                theme::text().primary,
                search,
            );
            agent_search_label(
                ui,
                uri,
                theme::typography::code_small(),
                theme::text().primary,
                search,
            );
            agent_search_label(
                ui,
                text,
                theme::typography::code_small(),
                theme::text().primary,
                search,
            );
        }
        DisplayContent::BlobResource {
            uri,
            mime_type,
            encoded_bytes,
        } => {
            agent_search_label(
                ui,
                &format!(
                    "Binary resource · {} · {encoded_bytes} encoded bytes",
                    mime_type.as_deref().unwrap_or("unknown type")
                ),
                theme::typography::body(),
                theme::text().primary,
                search,
            );
            agent_search_label(
                ui,
                uri,
                theme::typography::code_small(),
                theme::text().primary,
                search,
            );
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AgentDiffKind {
    Context,
    Removed,
    Added,
    Omitted,
}

#[derive(Clone, Debug)]
struct AgentDiffLine {
    old_number: Option<usize>,
    new_number: Option<usize>,
    text: String,
    kind: AgentDiffKind,
    omitted: usize,
}

#[derive(Debug)]
struct AgentDiff {
    lines: Vec<AgentDiffLine>,
    preview: Option<Vec<AgentDiffLine>>,
    added: usize,
    removed: usize,
    old_line_count: usize,
    new_line_count: usize,
}

fn build_agent_diff(old_text: Option<&str>, new_text: &str) -> AgentDiff {
    let old = old_text.map_or_else(Vec::new, |text| text.lines().collect::<Vec<_>>());
    let new = new_text.lines().collect::<Vec<_>>();
    let mut lines = Vec::with_capacity(old.len() + new.len());

    if old_text.is_none() {
        for (index, text) in new.iter().enumerate() {
            lines.push(AgentDiffLine {
                old_number: None,
                new_number: Some(index + 1),
                text: (*text).to_owned(),
                kind: AgentDiffKind::Added,
                omitted: 0,
            });
        }
    } else if (old.len() + 1).saturating_mul(new.len() + 1) <= 250_000 {
        // ponytail: bounded LCS keeps normal tool diffs precise; large file replacements use the
        // linear fallback below instead of spending a frame on a quadratic comparison.
        let width = new.len() + 1;
        let mut common = vec![0_u32; (old.len() + 1) * width];
        for old_index in (0..old.len()).rev() {
            for new_index in (0..new.len()).rev() {
                common[old_index * width + new_index] = if old[old_index] == new[new_index] {
                    common[(old_index + 1) * width + new_index + 1] + 1
                } else {
                    common[(old_index + 1) * width + new_index]
                        .max(common[old_index * width + new_index + 1])
                };
            }
        }
        let (mut old_index, mut new_index) = (0, 0);
        while old_index < old.len() && new_index < new.len() {
            if old[old_index] == new[new_index] {
                lines.push(AgentDiffLine {
                    old_number: Some(old_index + 1),
                    new_number: Some(new_index + 1),
                    text: old[old_index].to_owned(),
                    kind: AgentDiffKind::Context,
                    omitted: 0,
                });
                old_index += 1;
                new_index += 1;
            } else if common[(old_index + 1) * width + new_index]
                >= common[old_index * width + new_index + 1]
            {
                lines.push(AgentDiffLine {
                    old_number: Some(old_index + 1),
                    new_number: None,
                    text: old[old_index].to_owned(),
                    kind: AgentDiffKind::Removed,
                    omitted: 0,
                });
                old_index += 1;
            } else {
                lines.push(AgentDiffLine {
                    old_number: None,
                    new_number: Some(new_index + 1),
                    text: new[new_index].to_owned(),
                    kind: AgentDiffKind::Added,
                    omitted: 0,
                });
                new_index += 1;
            }
        }
        while old_index < old.len() {
            lines.push(AgentDiffLine {
                old_number: Some(old_index + 1),
                new_number: None,
                text: old[old_index].to_owned(),
                kind: AgentDiffKind::Removed,
                omitted: 0,
            });
            old_index += 1;
        }
        while new_index < new.len() {
            lines.push(AgentDiffLine {
                old_number: None,
                new_number: Some(new_index + 1),
                text: new[new_index].to_owned(),
                kind: AgentDiffKind::Added,
                omitted: 0,
            });
            new_index += 1;
        }
    } else {
        let prefix = old
            .iter()
            .zip(&new)
            .take_while(|(before, after)| before == after)
            .count();
        let suffix = old[prefix..]
            .iter()
            .rev()
            .zip(new[prefix..].iter().rev())
            .take_while(|(before, after)| before == after)
            .count();
        for (index, text) in old.iter().take(prefix).enumerate() {
            lines.push(AgentDiffLine {
                old_number: Some(index + 1),
                new_number: Some(index + 1),
                text: (*text).to_owned(),
                kind: AgentDiffKind::Context,
                omitted: 0,
            });
        }
        for (index, text) in old[prefix..old.len() - suffix].iter().enumerate() {
            lines.push(AgentDiffLine {
                old_number: Some(prefix + index + 1),
                new_number: None,
                text: (*text).to_owned(),
                kind: AgentDiffKind::Removed,
                omitted: 0,
            });
        }
        for (index, text) in new[prefix..new.len() - suffix].iter().enumerate() {
            lines.push(AgentDiffLine {
                old_number: None,
                new_number: Some(prefix + index + 1),
                text: (*text).to_owned(),
                kind: AgentDiffKind::Added,
                omitted: 0,
            });
        }
        for index in 0..suffix {
            let old_index = old.len() - suffix + index;
            let new_index = new.len() - suffix + index;
            lines.push(AgentDiffLine {
                old_number: Some(old_index + 1),
                new_number: Some(new_index + 1),
                text: old[old_index].to_owned(),
                kind: AgentDiffKind::Context,
                omitted: 0,
            });
        }
    }

    let added = lines
        .iter()
        .filter(|line| line.kind == AgentDiffKind::Added)
        .count();
    let removed = lines
        .iter()
        .filter(|line| line.kind == AgentDiffKind::Removed)
        .count();
    let mut compact = Vec::with_capacity(lines.len());
    let mut start = 0;
    while start < lines.len() {
        if lines[start].kind != AgentDiffKind::Context {
            compact.push(lines[start].clone());
            start += 1;
            continue;
        }
        let mut end = start + 1;
        while end < lines.len() && lines[end].kind == AgentDiffKind::Context {
            end += 1;
        }
        if end - start > 6 {
            compact.extend_from_slice(&lines[start..start + 3]);
            compact.push(AgentDiffLine {
                old_number: None,
                new_number: None,
                text: String::new(),
                kind: AgentDiffKind::Omitted,
                omitted: end - start - 6,
            });
            compact.extend_from_slice(&lines[end - 3..end]);
        } else {
            compact.extend_from_slice(&lines[start..end]);
        }
        start = end;
    }

    let preview = agent_diff_preview(&compact);
    AgentDiff {
        lines: compact,
        preview,
        added,
        removed,
        old_line_count: old.len(),
        new_line_count: new.len(),
    }
}

#[derive(Clone, Default)]
struct AgentDiffCache {
    old_text: Option<String>,
    new_text: String,
    diff: Option<Arc<AgentDiff>>,
}

fn cached_agent_diff(
    ui: &mut egui::Ui,
    id: Id,
    old_text: Option<&str>,
    new_text: &str,
) -> Arc<AgentDiff> {
    let cache_id = id.with("model");
    let stale = ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentDiffCache>(cache_id);
        cache.diff.is_none() || cache.old_text.as_deref() != old_text || cache.new_text != new_text
    });
    if stale {
        let diff = Arc::new(build_agent_diff(old_text, new_text));
        ui.data_mut(|data| {
            let cache = data.get_temp_mut_or_default::<AgentDiffCache>(cache_id);
            cache.old_text = old_text.map(str::to_owned);
            cache.new_text.clear();
            cache.new_text.push_str(new_text);
            cache.diff = Some(diff);
        });
    }
    ui.data_mut(|data| {
        Arc::clone(
            data.get_temp_mut_or_default::<AgentDiffCache>(cache_id)
                .diff
                .as_ref()
                .expect("agent diff was cached"),
        )
    })
}

fn agent_diff_preview(lines: &[AgentDiffLine]) -> Option<Vec<AgentDiffLine>> {
    if lines.len() <= AGENT_DIFF_PREVIEW_ROWS {
        return None;
    }
    let tail = AGENT_DIFF_PREVIEW_ROWS - AGENT_DIFF_PREVIEW_HEAD - 1;
    let mut preview = Vec::with_capacity(AGENT_DIFF_PREVIEW_ROWS);
    preview.extend_from_slice(&lines[..AGENT_DIFF_PREVIEW_HEAD]);
    preview.push(AgentDiffLine {
        old_number: None,
        new_number: None,
        text: String::new(),
        kind: AgentDiffKind::Omitted,
        omitted: lines.len() - AGENT_DIFF_PREVIEW_HEAD - tail,
    });
    preview.extend_from_slice(&lines[lines.len() - tail..]);
    Some(preview)
}

fn tool_contains_diff(tool: &crate::agent::controller::ToolActivity) -> bool {
    tool.detail.as_ref().is_some_and(|detail| {
        detail
            .content
            .iter()
            .any(|content| matches!(content, ToolOutput::Diff { .. }))
    })
}

/// A tool card counts as a subagent when the ACP tool call advertised the
/// `Task` kind or when a `cursor/task` notification supplied task content.
fn tool_is_subagent(tool: &crate::agent::controller::ToolActivity) -> bool {
    tool.kind.as_deref() == Some("Task")
        || tool.detail.as_ref().is_some_and(|detail| {
            detail
                .content
                .iter()
                .any(|content| matches!(content, ToolOutput::Task { .. }))
        })
}

fn agent_task_duration(duration_ms: u64) -> String {
    if duration_ms < 1_000 {
        format!("{duration_ms} ms")
    } else {
        format!("{:.1} s", duration_ms as f64 / 1_000.0)
    }
}

/// A clickable path label; every path the agent surfaces routes through this
/// so one click opens the file in the editor.
fn agent_path_link(
    ui: &mut egui::Ui,
    label: &str,
    search: Option<(&str, Option<usize>)>,
) -> egui::Response {
    ui.add(
        Label::new(agent_text_job(
            label,
            ui.available_width(),
            theme::typography::code_small(),
            theme::text().primary,
            search,
        ))
        .truncate()
        .sense(Sense::click()),
    )
    .on_hover_cursor(egui::CursorIcon::PointingHand)
    .on_hover_text("Open in editor")
}

const AGENT_IMAGE_PREVIEW_EDGE: u32 = 640;
const AGENT_IMAGE_PREVIEW_MAX_BYTES: u64 = 16 * 1024 * 1024;

#[derive(Clone)]
enum AgentImagePreview {
    Unavailable,
    Loaded(egui::TextureHandle),
}

/// Inline preview for a generated image. The decode happens once on first
/// expand and is cached (including failures) so a frame never re-reads disk.
fn agent_generated_image_preview(ui: &mut egui::Ui, path: &Path) -> Option<egui::Response> {
    let cache_id = Id::new(("agent_generated_image", path));
    let cached = ui.data(|data| data.get_temp::<AgentImagePreview>(cache_id));
    let cached = cached.unwrap_or_else(|| {
        let loaded = load_agent_image_preview(ui.ctx(), path)
            .map_or(AgentImagePreview::Unavailable, AgentImagePreview::Loaded);
        ui.data_mut(|data| data.insert_temp(cache_id, loaded.clone()));
        loaded
    });
    match cached {
        AgentImagePreview::Unavailable => None,
        AgentImagePreview::Loaded(texture) => {
            let size = texture.size_vec2();
            let scale = (ui.available_width() / size.x).min(1.0);
            Some(
                ui.add(
                    egui::Image::from_texture((texture.id(), size))
                        .fit_to_exact_size(size * scale)
                        .corner_radius(6)
                        .sense(Sense::click()),
                )
                .on_hover_cursor(egui::CursorIcon::PointingHand)
                .on_hover_text("Open in editor"),
            )
        }
    }
}

fn load_agent_image_preview(ctx: &egui::Context, path: &Path) -> Option<egui::TextureHandle> {
    let metadata = fs::metadata(path).ok()?;
    if !metadata.is_file() || metadata.len() > AGENT_IMAGE_PREVIEW_MAX_BYTES {
        return None;
    }
    let mut reader = image::ImageReader::open(path)
        .ok()?
        .with_guessed_format()
        .ok()?;
    let mut limits = image::Limits::default();
    limits.max_image_width = Some(16_384);
    limits.max_image_height = Some(16_384);
    limits.max_alloc = Some(128 * 1024 * 1024);
    reader.limits(limits);
    let image = reader.decode().ok()?;
    let image =
        if image.width() > AGENT_IMAGE_PREVIEW_EDGE || image.height() > AGENT_IMAGE_PREVIEW_EDGE {
            image.thumbnail(AGENT_IMAGE_PREVIEW_EDGE, AGENT_IMAGE_PREVIEW_EDGE)
        } else {
            image
        };
    let size = [image.width() as usize, image.height() as usize];
    let pixels = image.into_rgba8();
    Some(ctx.load_texture(
        path.display().to_string(),
        egui::ColorImage::from_rgba_unmultiplied(size, pixels.as_raw()),
        egui::TextureOptions::LINEAR,
    ))
}

fn agent_tool_status(status: Option<&str>) -> (&'static str, Color32) {
    match status.unwrap_or_default() {
        "Completed" => ("Completed", theme::ink(theme::semantic().success)),
        "InProgress" | "Pending" => ("Running", theme::accent()),
        "Failed" => ("Failed", theme::ink(theme::semantic().danger)),
        "Cancelled" => ("Cancelled", theme::text().muted),
        _ => ("", theme::text().muted),
    }
}

fn paint_agent_disclosure(ui: &mut egui::Ui, openness: f32, response: &egui::Response) {
    let center = response.rect.center() + egui::vec2(0.0, 1.0);
    let box_rect = egui::Rect::from_center_size(center, egui::Vec2::splat(icons::GRID * 0.75));
    let color = ui.style().interact(response).fg_stroke.color;
    let shapes = icons::shapes(
        if openness > 0.5 {
            Icon::ChevronDown
        } else {
            Icon::ChevronRight
        },
        box_rect,
        color,
    );
    for shape in shapes {
        ui.painter().add(shape);
    }
}

fn paint_cursor_mark(painter: &egui::Painter, rect: egui::Rect, color: Color32) {
    let center = rect.center();
    let scale = rect.width().min(rect.height()) / 15.0;
    let top = center + egui::vec2(0.0, -7.0 * scale);
    let upper_right = center + egui::vec2(6.1 * scale, -3.5 * scale);
    let lower_right = center + egui::vec2(6.1 * scale, 3.5 * scale);
    let bottom = center + egui::vec2(0.0, 7.0 * scale);
    let lower_left = center + egui::vec2(-6.1 * scale, 3.5 * scale);
    let upper_left = center + egui::vec2(-6.1 * scale, -3.5 * scale);
    for points in [
        vec![top, upper_right, upper_left],
        vec![upper_right, lower_right, bottom],
        vec![upper_left, center, bottom, lower_left],
    ] {
        painter.add(egui::Shape::convex_polygon(
            points,
            color,
            egui::Stroke::NONE,
        ));
    }
}

fn paint_provider_icon(
    painter: &egui::Painter,
    rect: egui::Rect,
    icon: ProviderIcon,
    color: Color32,
) {
    match icon {
        ProviderIcon::CursorMark => paint_cursor_mark(painter, rect, color),
        ProviderIcon::OpenAiMark | ProviderIcon::AnthropicMark => {
            let (cache_key, name, bytes) = match icon {
                ProviderIcon::OpenAiMark => (
                    "provider_openai_texture",
                    "OpenAI logo",
                    &include_bytes!("../assets/icons/provider-openai.png")[..],
                ),
                ProviderIcon::AnthropicMark => (
                    "provider_anthropic_texture",
                    "Anthropic logo",
                    &include_bytes!("../assets/icons/provider-anthropic.png")[..],
                ),
                ProviderIcon::CursorMark => unreachable!(),
            };
            let ctx = painter.ctx();
            let cache_id = Id::new(cache_key);
            let texture = ctx.data_mut(|data| data.get_temp::<egui::TextureHandle>(cache_id));
            let texture = texture.or_else(|| {
                let pixels = image::load_from_memory(bytes).ok()?.into_rgba8();
                let size = [pixels.width() as usize, pixels.height() as usize];
                let texture = ctx.load_texture(
                    name,
                    egui::ColorImage::from_rgba_unmultiplied(size, pixels.as_raw()),
                    egui::TextureOptions::LINEAR,
                );
                ctx.data_mut(|data| data.insert_temp(cache_id, texture.clone()));
                Some(texture)
            });
            if let Some(texture) = texture {
                let side = rect.width().min(rect.height());
                let rect = egui::Rect::from_center_size(rect.center(), egui::vec2(side, side));
                painter.image(
                    texture.id(),
                    rect,
                    egui::Rect::from_min_max(egui::Pos2::ZERO, egui::pos2(1.0, 1.0)),
                    color,
                );
            }
        }
    }
}

/// The "connecting to the agent harness" state, shown while the sidebar or
/// agentic view waits for a session: a breathing provider mark, a headline,
/// a status line, and a progress bar — determinate while a download reports
/// its size, a sweeping segment otherwise.
fn draw_agent_connecting(
    ui: &mut egui::Ui,
    provider: ProviderId,
    headline: &str,
    detail: &str,
    progress: Option<f32>,
) {
    let region = ui.max_rect();
    let block = egui::Rect::from_center_size(
        egui::pos2(region.center().x, region.top() + region.height() * 0.42),
        egui::vec2(region.width().min(280.0), 150.0),
    );
    let time = ui.input(|input| input.time);
    ui.scope_builder(
        UiBuilder::new().id_salt("agent_connecting").max_rect(block),
        |ui| {
            ui.vertical_centered(|ui| {
                let pulse =
                    0.55 + 0.45 * (0.5 + 0.5 * (time * std::f64::consts::TAU / 2.4).sin()) as f32;
                let (mark, _) = ui.allocate_exact_size(egui::Vec2::splat(40.0), Sense::hover());
                paint_provider_icon(
                    ui.painter(),
                    mark,
                    provider_descriptor(provider).icon,
                    theme::text().primary.gamma_multiply(pulse),
                );
                ui.add_space(theme::space::LARGE);
                ui.label(
                    RichText::new(headline)
                        .size(theme::typography::TITLE_SIZE)
                        .strong()
                        .color(theme::text().primary),
                );
                ui.add_space(theme::space::TIGHT);
                ui.label(
                    RichText::new(detail)
                        .size(theme::typography::SMALL_SIZE)
                        .color(theme::text().muted),
                );
                ui.add_space(theme::space::LARGE);
                let (track, _) = ui.allocate_exact_size(
                    egui::vec2(ui.available_width().min(220.0), 3.0),
                    Sense::hover(),
                );
                ui.painter()
                    .rect_filled(track, 2.0, theme::border::hairline_color());
                let fill = match progress {
                    Some(progress) => {
                        track.with_max_x(track.left() + track.width() * progress.clamp(0.02, 1.0))
                    }
                    None => {
                        let segment = track.width() * 0.35;
                        let travel = track.width() + segment;
                        let offset = ((time * 140.0) % f64::from(travel)) as f32;
                        egui::Rect::from_min_max(
                            egui::pos2(track.left() + offset - segment, track.top()),
                            egui::pos2(track.left() + offset, track.bottom()),
                        )
                        .intersect(track)
                    }
                };
                if fill.width() > 0.0 {
                    ui.painter().rect_filled(fill, 2.0, theme::accent());
                }
            });
        },
    );
    ui.ctx().request_repaint_after(Duration::from_millis(33));
}

fn draw_provider_identity(ui: &mut egui::Ui, provider: ProviderId) {
    let provider = provider_descriptor(provider);
    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = 5.0;
        let (rect, _) = ui.allocate_exact_size(egui::vec2(17.0, 20.0), Sense::hover());
        paint_provider_icon(ui.painter(), rect, provider.icon, theme::text().primary);
        ui.label(
            RichText::new(provider.display_name)
                .size(theme::typography::BODY_SIZE)
                .strong()
                .color(theme::text().primary),
        );
    });
    ui.add_space(5.0);
}

/// A live provider-branded pulse that follows the latest transcript output.
fn draw_agent_working(ui: &mut egui::Ui, provider: ProviderId) -> egui::Response {
    let provider = provider_descriptor(provider);
    let time = ui.input(|input| input.time);
    let (_, rect) = ui.allocate_space(egui::vec2(ui.available_width(), 36.0));
    let response = ui.interact(rect, Id::new("agent_working"), Sense::hover());
    let center = egui::pos2(rect.left() + 14.0, rect.center().y);
    let pulse = (0.5 + 0.5 * (time * std::f64::consts::TAU / 1.8).sin()) as f32;
    ui.painter()
        .circle_filled(center, 11.0, theme::state::selected());
    ui.painter().circle_stroke(
        center,
        12.0 + pulse * 1.5,
        egui::Stroke::new(1.0, theme::accent().gamma_multiply(0.45 + pulse * 0.4)),
    );
    paint_provider_icon(
        ui.painter(),
        egui::Rect::from_center_size(center, egui::Vec2::splat(14.0)),
        provider.icon,
        theme::text().primary,
    );

    let label = format!("{} is working", provider.display_name);
    let galley = ui.painter().layout_no_wrap(
        label,
        theme::typography::small(),
        theme::text().secondary,
    );
    let text_pos = egui::pos2(rect.left() + 36.0, rect.center().y - galley.size().y * 0.5);
    let dots_left = text_pos.x + galley.size().x + 10.0;
    ui.painter()
        .galley(text_pos, galley, theme::text().secondary);
    for index in 0..3 {
        let wave = (0.5
            + 0.5
                * ((time * 2.4 - f64::from(index) * 0.18) * std::f64::consts::TAU).sin())
            as f32;
        ui.painter().circle_filled(
            egui::pos2(dots_left + index as f32 * 7.0, rect.center().y - wave * 2.0),
            1.6,
            theme::accent().gamma_multiply(0.35 + wave * 0.65),
        );
    }
    ui.ctx().request_repaint_after(Duration::from_millis(33));
    response
}

fn draw_provider_selector_identity(
    ui: &mut egui::Ui,
    provider: ProviderId,
    enabled: bool,
) -> egui::Response {
    let provider = provider_descriptor(provider);
    let response = ui
        .add_enabled_ui(enabled, |ui| {
            let text_color = if ui.is_enabled() {
                theme::text().primary
            } else {
                theme::text_disabled()
            };
            let galley = ui.painter().layout_no_wrap(
                provider.display_name.to_owned(),
                theme::typography::body(),
                text_color,
            );
            let (rect, response) =
                ui.allocate_exact_size(egui::vec2(41.0 + galley.size().x, 20.0), Sense::click());
            if response.hovered() || response.is_pointer_button_down_on() {
                ui.painter().rect_filled(
                    rect.expand2(egui::vec2(4.0, 2.0)),
                    5.0,
                    if response.is_pointer_button_down_on() {
                        theme::state::selected()
                    } else {
                        theme::state::hover()
                    },
                );
            }
            let icon = egui::Rect::from_center_size(
                egui::pos2(rect.left() + 7.5, rect.center().y),
                egui::vec2(15.0, 18.0),
            );
            paint_provider_icon(ui.painter(), icon, provider.icon, text_color);
            let text_pos = egui::pos2(rect.left() + 20.0, rect.center().y - galley.size().y * 0.5);
            let text_right = text_pos.x + galley.size().x;
            ui.painter().galley(text_pos, galley, text_color);
            icons::paint(
                ui.painter(),
                Icon::ChevronDown,
                egui::Rect::from_center_size(
                    egui::pos2(text_right + 14.0, rect.center().y),
                    egui::Vec2::splat(icons::GRID),
                ),
                text_color,
            );
            response
        })
        .inner;
    let label = format!("Select ACP provider: {}", provider.display_name);
    response.widget_info(|| {
        egui::WidgetInfo::labeled(egui::WidgetType::Button, enabled, label.clone())
    });
    response.on_hover_text(label)
}

/// Sidebar and agentic mode lay the same transcript out at two different
/// widths; keeping a galley per width (most recent first, capped) makes
/// toggling between them free instead of relayouting every item.
const AGENT_GALLEY_WIDTH_SLOTS: usize = 2;

#[derive(Clone, Default)]
struct AgentMarkdownCache {
    source: String,
    galleys: Vec<(u32, Arc<egui::Galley>)>,
}

#[derive(Clone, Default)]
struct AgentCodeCache {
    source: String,
    path: PathBuf,
    galleys: Vec<(u32, Arc<egui::Galley>)>,
}

#[derive(Clone)]
struct AgentSyntaxLines {
    job: LayoutJob,
    /// Byte range in `job.text` for each highlighted source line, keyed by the
    /// 1-based line number in the original file.
    ranges: HashMap<usize, std::ops::Range<usize>>,
}

#[derive(Clone, Default)]
struct AgentSyntaxLinesCache {
    source: String,
    path: PathBuf,
    needed: Vec<usize>,
    lines: Option<Arc<AgentSyntaxLines>>,
}

/// Highlights only the lines a diff card actually renders (`needed`, sorted
/// 1-based line numbers). Whole-file highlighting cost ~160 ms for a 2 000-line
/// HTML file per version, which froze the first sidebar frame; a collapsed
/// preview needs about ten lines. The trade-off is that highlighting starts
/// from a default parser state at the first rendered line, so a hunk opening
/// mid-construct can color slightly differently than the editor.
fn agent_syntax_lines(
    ui: &mut egui::Ui,
    id: Id,
    path: &Path,
    source: &str,
    needed: &[usize],
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
) -> Arc<AgentSyntaxLines> {
    let stale = ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentSyntaxLinesCache>(id);
        cache.lines.is_none()
            || cache.path != path
            || cache.needed != needed
            || cache.source != source
    });
    if stale {
        let mut hunk = String::new();
        let mut ranges = HashMap::with_capacity(needed.len());
        let mut wanted = needed.iter().copied().peekable();
        for (index, line) in source.lines().enumerate() {
            let Some(&next) = wanted.peek() else {
                break;
            };
            if index + 1 == next {
                wanted.next();
                let start = hunk.len();
                hunk.push_str(line);
                ranges.insert(index + 1, start..hunk.len());
                hunk.push('\n');
            }
        }
        let syntax = syntaxes.detect(path, false);
        let job = highlighter
            .highlight_job(&hunk, syntax, syntaxes.set(), f32::INFINITY)
            .unwrap_or_else(|_| plain_text_job(&hunk, f32::INFINITY));
        let lines = Arc::new(AgentSyntaxLines { job, ranges });
        ui.data_mut(|data| {
            let cache = data.get_temp_mut_or_default::<AgentSyntaxLinesCache>(id);
            cache.source.clear();
            cache.source.push_str(source);
            cache.path = path.to_path_buf();
            cache.needed = needed.to_vec();
            cache.lines = Some(lines);
        });
    }
    ui.data_mut(|data| {
        Arc::clone(
            data.get_temp_mut_or_default::<AgentSyntaxLinesCache>(id)
                .lines
                .as_ref()
                .expect("agent syntax lines were cached"),
        )
    })
}

/// `tinted` marks a line sitting on an added/removed wash, whose code colors
/// are lifted through `theme::diff::code` so they keep their editor contrast.
fn append_agent_syntax_line(
    target: &mut LayoutJob,
    highlighted: &AgentSyntaxLines,
    line_number: usize,
    fallback: &str,
    tinted: bool,
) {
    let Some(range) = highlighted.ranges.get(&line_number) else {
        target.append(
            fallback,
            0.0,
            TextFormat {
                font_id: theme::typography::code_small(),
                color: if tinted {
                    theme::text().primary
                } else {
                    theme::text().secondary
                },
                ..TextFormat::default()
            },
        );
        return;
    };
    for section in &highlighted.job.sections {
        let start = section.byte_range.start.0.max(range.start);
        let end = section.byte_range.end.0.min(range.end);
        if start < end {
            let mut format = section.format.clone();
            format.font_id.size = 12.0;
            if tinted {
                format.color = theme::diff::code(format.color);
            }
            target.append(&highlighted.job.text[start..end], 0.0, format);
        }
    }
}

// The renderer needs syntax, width, cache identity, and an optional search overlay together.
#[expect(clippy::too_many_arguments)]
fn agent_code_galley(
    ui: &mut egui::Ui,
    id: Id,
    path: &Path,
    source: &str,
    width: f32,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
    search: Option<(&str, Option<usize>)>,
) -> Arc<egui::Galley> {
    let width_key = width.round().to_bits();
    if let Some((query, active)) = search {
        let syntax = syntaxes.detect(path, false);
        let mut job = highlighter
            .highlight_job(source, syntax, syntaxes.set(), width)
            .unwrap_or_else(|_| plain_text_job(source, width));
        job.wrap.break_anywhere = true;
        for section in &mut job.sections {
            section.format.font_id.size = 12.5;
        }
        let matches = match_spans(&job.text, query);
        let job = find_highlighted_job(&job, &matches, active.unwrap_or(usize::MAX));
        return ui.fonts_mut(|fonts| fonts.layout_job(job));
    }
    let cached = ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentCodeCache>(id);
        if cache.path != path || cache.source != source {
            return None;
        }
        cache
            .galleys
            .iter()
            .position(|(key, _)| *key == width_key)
            .map(|index| {
                let entry = cache.galleys.remove(index);
                let galley = Arc::clone(&entry.1);
                cache.galleys.insert(0, entry);
                galley
            })
    });
    if let Some(galley) = cached {
        return galley;
    }
    let syntax = syntaxes.detect(path, false);
    let mut job = highlighter
        .highlight_job(source, syntax, syntaxes.set(), width)
        .unwrap_or_else(|_| plain_text_job(source, width));
    job.wrap.break_anywhere = true;
    for section in &mut job.sections {
        section.format.font_id.size = 12.5;
    }
    let galley = ui.fonts_mut(|fonts| fonts.layout_job(job));
    ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentCodeCache>(id);
        if cache.path != path || cache.source != source {
            cache.source.clear();
            cache.source.push_str(source);
            cache.path = path.to_path_buf();
            cache.galleys.clear();
        }
        cache.galleys.insert(0, (width_key, Arc::clone(&galley)));
        cache.galleys.truncate(AGENT_GALLEY_WIDTH_SLOTS);
    });
    galley
}

fn agent_markdown_galley(
    ui: &mut egui::Ui,
    id: Id,
    source: &str,
    width: f32,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
    search: Option<(&str, Option<usize>)>,
) -> Arc<egui::Galley> {
    let width_key = width.round().to_bits();
    if let Some((query, active)) = search {
        let job = markdown::compact_layout(source, width, |language, code| {
            let syntax = language
                .map(|language| syntaxes.detect_token(language))
                .unwrap_or_else(|| syntaxes.plain_text());
            highlighter
                .highlight_job(code, syntax, syntaxes.set(), width)
                .ok()
        });
        let matches = match_spans(&job.text, query);
        let job = find_highlighted_job(&job, &matches, active.unwrap_or(usize::MAX));
        return ui.fonts_mut(|fonts| fonts.layout_job(job));
    }
    let cached = ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentMarkdownCache>(id);
        if cache.source != source {
            return None;
        }
        cache
            .galleys
            .iter()
            .position(|(key, _)| *key == width_key)
            .map(|index| {
                let entry = cache.galleys.remove(index);
                let galley = Arc::clone(&entry.1);
                cache.galleys.insert(0, entry);
                galley
            })
    });
    if let Some(galley) = cached {
        return galley;
    }
    let job = markdown::compact_layout(source, width, |language, code| {
        let syntax = language
            .map(|language| syntaxes.detect_token(language))
            .unwrap_or_else(|| syntaxes.plain_text());
        highlighter
            .highlight_job(code, syntax, syntaxes.set(), width)
            .ok()
    });
    let galley = ui.fonts_mut(|fonts| fonts.layout_job(job));
    ui.data_mut(|data| {
        let cache = data.get_temp_mut_or_default::<AgentMarkdownCache>(id);
        if cache.source != source {
            cache.source.clear();
            cache.source.push_str(source);
            cache.galleys.clear();
        }
        cache.galleys.insert(0, (width_key, Arc::clone(&galley)));
        cache.galleys.truncate(AGENT_GALLEY_WIDTH_SLOTS);
    });
    galley
}

fn agent_text_job(
    text: &str,
    width: f32,
    font_id: egui::FontId,
    color: Color32,
    search: Option<(&str, Option<usize>)>,
) -> LayoutJob {
    let mut job = LayoutJob::simple(text.to_owned(), font_id, color, width);
    job.wrap.break_anywhere = true;
    if let Some((query, active)) = search {
        job = find_highlighted_job(
            &job,
            &match_spans(text, query),
            active.unwrap_or(usize::MAX),
        );
    }
    job
}

fn agent_search_label(
    ui: &mut egui::Ui,
    text: &str,
    font_id: egui::FontId,
    color: Color32,
    search: Option<(&str, Option<usize>)>,
) -> egui::Response {
    let job = agent_text_job(text, ui.available_width(), font_id, color, search);
    ui.add(Label::new(job).wrap())
}

fn agent_tool_title(
    ui: &mut egui::Ui,
    id: Id,
    title: &str,
    width: f32,
    search: Option<(&str, Option<usize>)>,
) -> egui::Response {
    if search.is_some() {
        return ui
            .allocate_ui_with_layout(
                egui::vec2(width, 24.0),
                Layout::left_to_right(Align::Center),
                |ui| {
                    ui.set_width(width);
                    ui.add(
                        Label::new(agent_text_job(
                            title,
                            width,
                            theme::typography::body(),
                            theme::text().primary,
                            search,
                        ))
                        .truncate()
                        .sense(Sense::click()),
                    )
                },
            )
            .inner;
    }
    let Some((action, path)) = title.split_once(' ').filter(|(action, path)| {
        !path.is_empty()
            && (action.eq_ignore_ascii_case("Read") || action.eq_ignore_ascii_case("Edit"))
    }) else {
        return ui
            .allocate_ui_with_layout(
                egui::vec2(width, 24.0),
                Layout::left_to_right(Align::Center),
                |ui| {
                    ui.set_width(width);
                    ui.add(
                        Label::new(
                            RichText::new(title)
                                .size(theme::typography::BODY_SIZE)
                                .color(theme::text().primary),
                        )
                        .truncate()
                        .sense(Sense::click()),
                    )
                },
            )
            .inner;
    };

    let (rect, response) = ui.allocate_exact_size(egui::vec2(width, 24.0), Sense::click());
    response.widget_info(|| {
        egui::WidgetInfo::labeled(egui::WidgetType::Button, ui.is_enabled(), title)
    });
    let font = theme::typography::body();
    let action =
        ui.painter()
            .layout_no_wrap(format!("{action} "), font.clone(), theme::text().primary);
    let path = ui
        .painter()
        .layout_no_wrap(path.to_owned(), font, theme::text().primary);
    let y = rect.center().y - action.size().y * 0.5;
    ui.painter().with_clip_rect(rect).galley(
        egui::pos2(rect.left(), y),
        action.clone(),
        theme::text().primary,
    );
    let path_left = (rect.left() + action.size().x).min(rect.right());
    let path_rect =
        egui::Rect::from_min_max(egui::pos2(path_left, rect.top()), rect.right_bottom());
    let overflow = (path.size().x - path_rect.width()).max(0.0);
    let animation_id = id.with("path_marquee");
    if response.hovered() && overflow > 0.0 {
        let now = ui.input(|input| input.time);
        let started = ui.data_mut(|data| {
            data.get_temp::<f64>(animation_id).unwrap_or_else(|| {
                data.insert_temp(animation_id, now);
                now
            })
        });
        let pause = 0.6;
        let travel = f64::from(overflow) / 24.0;
        let phase = (now - started).rem_euclid(pause + travel + 0.8);
        let offset = if phase < pause {
            0.0
        } else if phase < pause + travel {
            ((phase - pause) * 24.0) as f32
        } else {
            overflow
        };
        ui.painter().with_clip_rect(path_rect).galley(
            egui::pos2(path_rect.left() - offset, y),
            path,
            theme::text().primary,
        );
        ui.ctx().request_repaint_after(Duration::from_millis(16));
    } else {
        ui.data_mut(|data| data.remove::<f64>(animation_id));
        let path = egui::WidgetText::from(
            RichText::new(path.text())
                .font(theme::typography::body())
                .color(theme::text().primary),
        )
        .into_galley(
            ui,
            Some(egui::TextWrapMode::Truncate),
            path_rect.width(),
            egui::FontSelection::Default,
        );
        ui.painter().with_clip_rect(path_rect).galley(
            egui::pos2(path_rect.left(), y),
            path,
            theme::text().primary,
        );
    }
    response
}

fn agent_collapsing_header(
    ui: &mut egui::Ui,
    id_salt: impl egui::AsIdSalt,
    title: &str,
    status: Option<&str>,
    width: f32,
    search: Option<(&str, Option<usize>)>,
    default_open: bool,
    add_body: impl FnOnce(&mut egui::Ui),
) {
    let id = ui.make_persistent_id(id_salt);
    let mut state = egui::collapsing_header::CollapsingState::load_with_default_open(
        ui.ctx(),
        id,
        default_open,
    );
    if search.is_some() {
        state.set_open(true);
    }
    let title_line = title
        .lines()
        .next()
        .map(str::trim)
        .filter(|title| !title.is_empty())
        .unwrap_or("Tool activity");
    let frame = egui::Frame::new()
        .fill(theme::surface().raised)
        .stroke(egui::Stroke::new(1.0, theme::border::hairline_color()))
        .corner_radius(5);
    let content_width = (width - frame.total_margin().sum().x).max(0.0);
    frame.show(ui, |ui| {
        ui.set_width(content_width);
        let card_right = ui.max_rect().right();
        egui::Frame::new()
            .inner_margin(egui::Margin {
                left: 8,
                right: 8,
                top: 8,
                bottom: 6,
            })
            .show(ui, |ui| {
                let (label, color) = agent_tool_status(status);
                let completed = status == Some("Completed");
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = 6.0;
                    ui.spacing_mut().icon_width = 24.0;
                    state.show_toggle_button(ui, paint_agent_disclosure);
                    let status_width = if completed {
                        24.0
                    } else if label.is_empty() {
                        0.0
                    } else {
                        52.0
                    };
                    let status_spacing = if label.is_empty() {
                        0.0
                    } else {
                        ui.spacing().item_spacing.x
                    };
                    let title_width =
                        (ui.available_width() - status_width - status_spacing).max(0.0);
                    let response = agent_tool_title(ui, id, title_line, title_width, search)
                        .on_hover_text(title);
                    if response.clicked() {
                        state.toggle(ui);
                    }
                    if completed {
                        let (rect, response) =
                            ui.allocate_exact_size(egui::vec2(24.0, 24.0), Sense::hover());
                        response.widget_info(|| {
                            egui::WidgetInfo::labeled(
                                egui::WidgetType::Label,
                                ui.is_enabled(),
                                label,
                            )
                        });
                        icons::paint(
                            ui.painter(),
                            Icon::CheckCircle,
                            egui::Rect::from_center_size(
                                rect.center(),
                                egui::Vec2::splat(icons::GRID),
                            ),
                            color,
                        );
                    } else if !label.is_empty() {
                        ui.add_sized(
                            egui::vec2(status_width, 24.0),
                            Label::new(
                                RichText::new(label)
                                    .size(theme::typography::MICRO_SIZE)
                                    .color(color),
                            ),
                        );
                    }
                });
            });
        state.show_body_unindented(ui, |ui| {
            ui.set_width((card_right - ui.cursor().left()).max(0.0));
            ui.painter().hline(
                ui.available_rect_before_wrap().x_range(),
                ui.cursor().top(),
                egui::Stroke::new(1.0, theme::border::hairline_color()),
            );
            if default_open {
                add_body(ui);
            } else {
                egui::Frame::new()
                    .inner_margin(egui::Margin::symmetric(9, 8))
                    .show(ui, |ui| {
                        let width = ui.available_width();
                        ui.set_width(width);
                        ui.set_max_width(width);
                        add_body(ui);
                    });
            }
        });
    });
}

/// The session summary card: every file the agent modified, one row per file
/// with the accumulated added/removed line counts the state tracked as diffs
/// arrived. Returns the path the user clicked, if any.
fn draw_agent_changed_files(
    ui: &mut egui::Ui,
    root: &Path,
    changed_paths: &HashMap<PathBuf, FileChange>,
    search: Option<(&str, Option<usize>)>,
) -> Option<PathBuf> {
    let mut rows = changed_paths.iter().collect::<Vec<_>>();
    rows.sort_by_key(|(path, _)| *path);
    let mut clicked = None;
    egui::Frame::new()
        .fill(theme::surface().raised)
        .stroke(egui::Stroke::new(1.0, theme::border::hairline_color()))
        .corner_radius(8)
        .inner_margin(egui::Margin::symmetric(12, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.label(
                RichText::new(format!(
                    "{} file{} changed",
                    rows.len(),
                    if rows.len() == 1 { "" } else { "s" }
                ))
                .size(theme::typography::SMALL_SIZE)
                .strong()
                .color(theme::text().secondary),
            );
            ui.add_space(theme::space::SNUG);
            ui.spacing_mut().item_spacing.y = 0.0;
            let mut search_offset = 0;
            for (path, stats) in rows {
                let (added, removed) = (stats.added, stats.removed);
                let (row, response) = ui.allocate_exact_size(
                    egui::vec2(ui.available_width(), theme::control::ROW),
                    Sense::click(),
                );
                let response = response
                    .on_hover_cursor(egui::CursorIcon::PointingHand)
                    .on_hover_text(format!("Open diff for {}", path.display()));
                if response.clicked() {
                    clicked = Some(path.clone());
                }
                if response.hovered() {
                    ui.painter().rect_filled(
                        row,
                        theme::corner(theme::radius::ROW),
                        theme::state::hover(),
                    );
                }
                let icon = egui::Rect::from_center_size(
                    egui::pos2(row.left() + 12.0, row.center().y),
                    egui::Vec2::splat(icons::GRID),
                );
                icons::paint(ui.painter(), Icon::File, icon, theme::text().muted);
                let mut counts_left = row.right() - theme::space::SNUG;
                if added > 0 || removed > 0 {
                    let removed_galley = ui.painter().layout_no_wrap(
                        format!("−{removed}"),
                        theme::typography::code_small(),
                        theme::ink(theme::semantic().danger),
                    );
                    counts_left -= removed_galley.size().x;
                    ui.painter().galley(
                        egui::pos2(counts_left, row.center().y - removed_galley.size().y * 0.5),
                        removed_galley,
                        theme::ink(theme::semantic().danger),
                    );
                    let added_galley = ui.painter().layout_no_wrap(
                        format!("+{added}"),
                        theme::typography::code_small(),
                        theme::ink(theme::semantic().success),
                    );
                    counts_left -= added_galley.size().x + theme::space::SNUG;
                    ui.painter().galley(
                        egui::pos2(counts_left, row.center().y - added_galley.size().y * 0.5),
                        added_galley,
                        theme::ink(theme::semantic().success),
                    );
                }
                let name = path
                    .file_name()
                    .unwrap_or(path.as_os_str())
                    .to_string_lossy();
                let directory = path
                    .parent()
                    .map(|parent| parent.strip_prefix(root).unwrap_or(parent))
                    .map(|parent| parent.display().to_string())
                    .filter(|parent| !parent.is_empty());
                let mut job = LayoutJob::default();
                job.append(
                    &name,
                    0.0,
                    TextFormat {
                        font_id: theme::typography::small(),
                        color: theme::text().primary,
                        ..TextFormat::default()
                    },
                );
                if let Some(directory) = directory {
                    job.append(
                        &directory,
                        theme::space::SMALL,
                        TextFormat {
                            font_id: theme::typography::micro(),
                            color: theme::text().muted,
                            ..TextFormat::default()
                        },
                    );
                }
                job.wrap.max_width =
                    (counts_left - theme::space::SMALL) - (row.left() + theme::space::XWIDE);
                job.wrap.max_rows = 1;
                job.wrap.break_anywhere = true;
                if let Some((query, active)) = search {
                    let matches = match_spans(&path.display().to_string(), query);
                    let local_active = active
                        .and_then(|active| active.checked_sub(search_offset))
                        .filter(|&active| active < matches.len());
                    search_offset += matches.len();
                    job = find_highlighted_job(
                        &job,
                        &match_spans(&job.text, query),
                        local_active.unwrap_or(usize::MAX),
                    );
                }
                let galley = ui.painter().layout_job(job);
                ui.painter().galley(
                    egui::pos2(
                        row.left() + theme::space::XWIDE,
                        row.center().y - galley.size().y * 0.5,
                    ),
                    galley,
                    theme::text().primary,
                );
            }
        });
    clicked
}

/// Returns true when the header path label was clicked.
// The shared card renderer keeps its syntax and optional search overlay explicit at the call site.
#[expect(clippy::too_many_arguments)]
fn draw_agent_diff(
    ui: &mut egui::Ui,
    id: Id,
    path: &Path,
    old_text: Option<&str>,
    new_text: &str,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
    search: Option<(&str, Option<usize>)>,
) -> bool {
    let mut path_clicked = false;
    let diff = cached_agent_diff(ui, id, old_text, new_text);
    let expanded_id = id.with("expanded");
    let expanded =
        search.is_some() || ui.data(|data| data.get_temp::<bool>(expanded_id).unwrap_or(false));
    let lines = (!expanded)
        .then_some(diff.preview.as_deref())
        .flatten()
        .unwrap_or(&diff.lines);
    let can_toggle = diff.lines.len() > AGENT_DIFF_PREVIEW_ROWS;
    let file_name = path
        .file_name()
        .unwrap_or(path.as_os_str())
        .to_string_lossy();
    ui.set_width(ui.available_width());
    egui::Frame::new()
        .fill(theme::surface().input)
        .show(ui, |ui| {
            egui::Frame::new()
                .inner_margin(egui::Margin::symmetric(10, 8))
                .show(ui, |ui| {
                    ui.horizontal(|ui| {
                        let header = ui
                            .add(
                                Label::new(agent_text_job(
                                    file_name.as_ref(),
                                    ui.available_width(),
                                    theme::typography::strong(),
                                    theme::text().primary,
                                    search,
                                ))
                                .sense(Sense::click()),
                            )
                            .on_hover_cursor(egui::CursorIcon::PointingHand)
                            .on_hover_text(format!("Open {}", path.display()));
                        path_clicked |= header.clicked();
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            ui.label(
                                RichText::new(format!("+{}  −{}", diff.added, diff.removed))
                                    .monospace()
                                    .size(theme::typography::MICRO_SIZE)
                                    .color(theme::text().muted),
                            );
                            ui.label(
                                RichText::new(if old_text.is_some() {
                                    "MODIFIED"
                                } else {
                                    "NEW FILE"
                                })
                                .size(theme::typography::MICRO_SIZE)
                                .strong()
                                .color(theme::accent()),
                            );
                        });
                    });
                });
            ui.painter().hline(
                ui.available_rect_before_wrap().x_range(),
                ui.cursor().top(),
                egui::Stroke::new(1.0, theme::border::strong_color()),
            );
            let row_search = search.map(|(query, active)| {
                let path_matches = match_spans(&path.display().to_string(), query).len();
                (
                    query,
                    active.and_then(|active| active.checked_sub(path_matches)),
                )
            });
            draw_agent_diff_rows(
                ui,
                id,
                path,
                &diff,
                lines,
                old_text,
                new_text,
                highlighter,
                syntaxes,
                row_search,
            );
            if can_toggle {
                let label = if expanded {
                    "Collapse diff".to_owned()
                } else {
                    format!("Show all {} lines", diff.lines.len())
                };
                let toggle = ui.add_sized(
                    egui::vec2(ui.available_width(), 40.0),
                    egui::Button::new(
                        RichText::new(label)
                            .size(theme::typography::MICRO_SIZE)
                            .color(theme::accent()),
                    )
                    .frame(false),
                );
                if toggle.clicked() {
                    ui.data_mut(|data| data.insert_temp(expanded_id, !expanded));
                    ui.ctx().request_repaint();
                }
            }
        });
    path_clicked
}

/// The diff line rows shared by the transcript card and the full-height diff
/// view: syntax highlighted, colored per kind, horizontally scrollable.
#[expect(clippy::too_many_arguments)]
fn draw_agent_diff_rows(
    ui: &mut egui::Ui,
    id: Id,
    path: &Path,
    diff: &AgentDiff,
    lines: &[AgentDiffLine],
    old_text: Option<&str>,
    new_text: &str,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
    search: Option<(&str, Option<usize>)>,
) {
    let mut needed_old = Vec::new();
    let mut needed_new = Vec::new();
    for line in lines {
        match line.kind {
            AgentDiffKind::Removed => needed_old.extend(line.old_number),
            AgentDiffKind::Added | AgentDiffKind::Context => needed_new.extend(line.new_number),
            AgentDiffKind::Omitted => {}
        }
    }
    for needed in [&mut needed_old, &mut needed_new] {
        needed.sort_unstable();
        needed.dedup();
    }
    let old_syntax = old_text.map(|text| {
        agent_syntax_lines(
            ui,
            id.with("old_syntax"),
            path,
            text,
            &needed_old,
            highlighter,
            syntaxes,
        )
    });
    let new_syntax = agent_syntax_lines(
        ui,
        id.with("new_syntax"),
        path,
        new_text,
        &needed_new,
        highlighter,
        syntaxes,
    );
    let old_digits = diff.old_line_count.max(1).ilog10() as usize + 1;
    let new_digits = diff.new_line_count.max(1).ilog10() as usize + 1;
    let longest = lines
        .iter()
        .map(|line| line.text.chars().count())
        .max()
        .unwrap_or(0);
    let content_width = ui.available_width();
    let desired_width =
        content_width.max(38.0 + (old_digits + new_digits + longest).min(240) as f32 * 7.3);
    ScrollArea::horizontal()
        .id_salt(id)
        .max_width(content_width)
        .auto_shrink([false, true])
        .scroll_bar_visibility(egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded)
        .show(ui, |ui| {
            ui.set_width(desired_width);
            ui.spacing_mut().item_spacing.y = 0.0;
            let mut search_offset = 0;
            for line in lines {
                let fill = match line.kind {
                    AgentDiffKind::Added => theme::diff::added(),
                    AgentDiffKind::Removed => theme::diff::removed(),
                    AgentDiffKind::Omitted => theme::surface().raised,
                    AgentDiffKind::Context => Color32::TRANSPARENT,
                };
                egui::Frame::new()
                    .fill(fill)
                    .inner_margin(egui::Margin::symmetric(9, 3))
                    .show(ui, |ui| {
                        ui.set_min_width(desired_width - 18.0);
                        if line.kind == AgentDiffKind::Omitted {
                            ui.label(
                                RichText::new(format!("⋯  {} lines hidden", line.omitted))
                                    .monospace()
                                    .size(theme::typography::MICRO_SIZE)
                                    .color(theme::text().muted),
                            );
                            return;
                        }
                        let old_number = line.old_number.map_or_else(
                            || " ".repeat(old_digits),
                            |number| format!("{number:>old_digits$}"),
                        );
                        let new_number = line.new_number.map_or_else(
                            || " ".repeat(new_digits),
                            |number| format!("{number:>new_digits$}"),
                        );
                        let (sign, color) = match line.kind {
                            AgentDiffKind::Added => ("+", theme::diff::added_ink()),
                            AgentDiffKind::Removed => ("−", theme::diff::removed_ink()),
                            AgentDiffKind::Context => (" ", theme::text().secondary),
                            AgentDiffKind::Omitted => unreachable!(),
                        };
                        let number_color = match line.kind {
                            AgentDiffKind::Added => theme::diff::added_number(),
                            AgentDiffKind::Removed => theme::diff::removed_number(),
                            AgentDiffKind::Context => theme::text_disabled(),
                            AgentDiffKind::Omitted => unreachable!(),
                        };
                        let mut job = LayoutJob::default();
                        job.append(
                            &format!("{old_number} {new_number}  "),
                            0.0,
                            TextFormat {
                                font_id: theme::typography::code_small(),
                                color: number_color,
                                ..TextFormat::default()
                            },
                        );
                        job.append(
                            &format!("{sign} "),
                            0.0,
                            TextFormat {
                                font_id: theme::typography::code_small(),
                                color,
                                ..TextFormat::default()
                            },
                        );
                        let highlighted = match line.kind {
                            AgentDiffKind::Removed => old_syntax.as_deref(),
                            AgentDiffKind::Added | AgentDiffKind::Context => Some(&*new_syntax),
                            AgentDiffKind::Omitted => unreachable!(),
                        };
                        let line_number = match line.kind {
                            AgentDiffKind::Removed => line.old_number,
                            AgentDiffKind::Added | AgentDiffKind::Context => line.new_number,
                            AgentDiffKind::Omitted => None,
                        };
                        let code_start = job.text.len();
                        if let (Some(highlighted), Some(line_number)) = (highlighted, line_number) {
                            append_agent_syntax_line(
                                &mut job,
                                highlighted,
                                line_number,
                                &line.text,
                                matches!(line.kind, AgentDiffKind::Added | AgentDiffKind::Removed),
                            );
                        }
                        let job = if let Some((query, active)) = search {
                            let matches = match_spans(&line.text, query)
                                .into_iter()
                                .map(|span| code_start + span.start..code_start + span.end)
                                .collect::<Vec<_>>();
                            let local_active = active
                                .and_then(|active| active.checked_sub(search_offset))
                                .filter(|&active| active < matches.len());
                            search_offset += matches.len();
                            find_highlighted_job(&job, &matches, local_active.unwrap_or(usize::MAX))
                        } else {
                            job
                        };
                        ui.add(
                            Label::new(job)
                                .wrap_mode(egui::TextWrapMode::Extend)
                                .selectable(true),
                        );
                    });
            }
        });
}

/// The identity row every full diff surface carries: file name, directory,
/// badge, session line counts, and the dismiss control. Expects a horizontal
/// context spanning the surface. Returns true when dismiss was clicked.
fn agent_diff_view_header(
    ui: &mut egui::Ui,
    root: &Path,
    path: &Path,
    diff: &AgentDiff,
    modified: bool,
    dismiss_label: &str,
) -> bool {
    let mut dismissed = false;
    let file_name = path
        .file_name()
        .unwrap_or(path.as_os_str())
        .to_string_lossy();
    let directory = path
        .parent()
        .map(|parent| parent.strip_prefix(root).unwrap_or(parent))
        .map(|parent| parent.display().to_string())
        .filter(|parent| !parent.is_empty());
    ui.label(
        RichText::new(file_name.as_ref())
            .size(theme::typography::BODY_SIZE)
            .strong()
            .color(theme::text().primary),
    );
    if let Some(directory) = directory {
        ui.add(
            Label::new(
                RichText::new(directory)
                    .size(theme::typography::MICRO_SIZE)
                    .color(theme::text().muted),
            )
            .truncate(),
        );
    }
    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
        dismissed = ui
            .add(
                egui::Button::new(
                    RichText::new(dismiss_label)
                        .size(theme::typography::SMALL_SIZE)
                        .color(theme::accent()),
                )
                .frame(false),
            )
            .on_hover_cursor(egui::CursorIcon::PointingHand)
            .clicked();
        ui.label(
            RichText::new(format!("+{}  −{}", diff.added, diff.removed))
                .monospace()
                .size(theme::typography::MICRO_SIZE)
                .color(theme::text().muted),
        );
        ui.label(
            RichText::new(if modified { "MODIFIED" } else { "NEW FILE" })
                .size(theme::typography::MICRO_SIZE)
                .strong()
                .color(theme::accent()),
        );
    });
    dismissed
}

/// The complete diff in a vertical scroll, below whichever header the surface
/// wears.
#[expect(clippy::too_many_arguments)]
fn draw_agent_diff_body(
    ui: &mut egui::Ui,
    id: Id,
    path: &Path,
    diff: &AgentDiff,
    old_text: Option<&str>,
    new_text: &str,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
) {
    ScrollArea::vertical()
        .id_salt(id.with("scroll"))
        .auto_shrink([false, false])
        .show(ui, |ui| {
            draw_agent_diff_rows(
                ui,
                id,
                path,
                diff,
                &diff.lines,
                old_text,
                new_text,
                highlighter,
                syntaxes,
                None,
            );
        });
}

/// The full-height diff for one changed file inside an IDE tab: a header with
/// the file identity, badge, and session line counts, then the complete diff
/// in a vertical scroll. The agentic side panel draws the same header inside
/// the titlebar strip instead. Returns true when dismiss was clicked.
#[expect(clippy::too_many_arguments)]
fn draw_agent_diff_view(
    ui: &mut egui::Ui,
    id: Id,
    root: &Path,
    path: &Path,
    old_text: Option<&str>,
    new_text: &str,
    dismiss_label: &str,
    highlighter: &Highlighter,
    syntaxes: &SyntaxManager,
) -> bool {
    let mut dismissed = false;
    ui.painter()
        .rect_filled(ui.max_rect(), 0.0, theme::surface().input);
    let diff = cached_agent_diff(ui, id, old_text, new_text);
    egui::Frame::new()
        .inner_margin(egui::Margin::symmetric(14, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.horizontal(|ui| {
                dismissed = agent_diff_view_header(
                    ui,
                    root,
                    path,
                    &diff,
                    old_text.is_some(),
                    dismiss_label,
                );
            });
        });
    ui.painter().hline(
        ui.available_rect_before_wrap().x_range(),
        ui.cursor().top(),
        egui::Stroke::new(1.0, theme::border::strong_color()),
    );
    draw_agent_diff_body(
        ui,
        id,
        path,
        &diff,
        old_text,
        new_text,
        highlighter,
        syntaxes,
    );
    dismissed
}

fn split_workspace(
    content: egui::Rect,
    explorer_open: bool,
    explorer_width: f32,
    agent_open: bool,
    agent_width: f32,
) -> (Option<egui::Rect>, egui::Rect, egui::Rect) {
    let right_width = if agent_open {
        agent_width.max(320.0).min(content.width() * 0.52)
    } else {
        0.0
    };
    let explorer_width = explorer_width
        .max(SIDEBAR_MIN_WIDTH)
        .min((content.width() - right_width - 160.0).max(SIDEBAR_MIN_WIDTH));
    let explorer = explorer_open
        .then(|| content.with_max_x((content.left() + explorer_width).min(content.right())));
    let agent = content.with_min_x((content.right() - right_width).max(content.left()));
    let editor_right = if agent_open {
        agent.left()
    } else {
        content.right()
    };
    let editor = egui::Rect::from_min_max(
        egui::pos2(
            explorer.map_or(content.left(), |rect| rect.right()),
            content.top(),
        ),
        egui::pos2(editor_right, content.bottom()),
    );
    (explorer, editor, agent)
}

fn split_agentic_workspace(
    content: egui::Rect,
    sidebar_open: bool,
    sidebar_width: f32,
) -> (Option<egui::Rect>, egui::Rect) {
    if !sidebar_open {
        return (None, content);
    }
    let rail_width = sidebar_width
        .min(content.width() * 0.36)
        .max(SIDEBAR_MIN_WIDTH.min(content.width()));
    let sessions = content.with_max_x(content.left() + rail_width);
    let agent = content.with_min_x(sessions.right());
    (Some(sessions), agent)
}

/// Carves the Cursor-style diff panel out of the agentic conversation
/// column: the panel takes the majority of the width while the conversation
/// keeps enough room for its composer. A column too narrow to hold both
/// shows the conversation only.
fn split_agentic_diff(content: egui::Rect, open: bool) -> (egui::Rect, Option<egui::Rect>) {
    if !open {
        return (content, None);
    }
    let panel_width = (content.width() * 0.55).min(content.width() - AGENTIC_DIFF_MIN_CONVERSATION);
    if panel_width < AGENTIC_DIFF_MIN_PANEL {
        return (content, None);
    }
    let panel = content.with_min_x(content.right() - panel_width);
    (content.with_max_x(panel.left()), Some(panel))
}

fn split_bottom_panel(
    content: egui::Rect,
    open: bool,
    requested_height: f32,
) -> (egui::Rect, Option<egui::Rect>) {
    if !open {
        return (content, None);
    }
    let max_height = (content.height() - WORKSPACE_MIN_HEIGHT).max(0.0);
    let height = requested_height.max(TERMINAL_MIN_HEIGHT).min(max_height);
    let split = content.bottom() - height;
    (content.with_max_y(split), Some(content.with_min_y(split)))
}

fn editor_column_content(rect: egui::Rect) -> egui::Rect {
    rect.with_min_y((rect.top() + TITLEBAR_HEIGHT).min(rect.bottom()))
}

fn split_pane_content(rect: egui::Rect, find_open: bool) -> (egui::Rect, Option<egui::Rect>) {
    let findbar =
        find_open.then(|| rect.with_min_y((rect.bottom() - FIND_BAR_HEIGHT).max(rect.top())));
    (
        rect.with_max_y(findbar.map_or(rect.bottom(), |bar| bar.top())),
        findbar,
    )
}

fn pane_focus_corner_radius(rect: egui::Rect, window: egui::Rect) -> egui::CornerRadius {
    let left = (rect.left() - window.left()).abs() <= 0.5;
    let right = (rect.right() - window.right()).abs() <= 0.5;
    let top = (rect.top() - window.top()).abs() <= 0.5;
    let bottom = (rect.bottom() - window.bottom()).abs() <= 0.5;
    egui::CornerRadius {
        nw: if left && top { WINDOW_CORNER_RADIUS } else { 0 },
        ne: if right && top {
            WINDOW_CORNER_RADIUS
        } else {
            0
        },
        sw: if left && bottom {
            WINDOW_CORNER_RADIUS
        } else {
            0
        },
        se: if right && bottom {
            WINDOW_CORNER_RADIUS
        } else {
            0
        },
    }
}

fn pane_header_and_content(
    titlebar: egui::Rect,
    editor: egui::Rect,
    pane: egui::Rect,
) -> (egui::Rect, egui::Rect) {
    if (pane.top() - editor.top()).abs() <= 0.5 {
        (
            egui::Rect::from_min_max(
                egui::pos2(pane.left(), titlebar.top()),
                egui::pos2(pane.right(), titlebar.bottom()),
            ),
            pane,
        )
    } else {
        let header = pane.with_max_y((pane.top() + PANE_TAB_HEIGHT).min(pane.bottom()));
        (header, pane.with_min_y(header.bottom()))
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum DropZone {
    Center,
    Left,
    Right,
    Top,
    Bottom,
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub(crate) struct PaneId(pub(crate) u64);

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum SplitAxis {
    Horizontal,
    Vertical,
}

#[derive(Clone)]
enum PaneNode {
    Leaf(PaneId),
    Split {
        id: u64,
        axis: SplitAxis,
        fraction: f32,
        first: Box<Self>,
        second: Box<Self>,
    },
}

#[derive(Clone)]
pub(crate) struct PaneLayout {
    root: PaneNode,
    next_id: u64,
    next_split_id: u64,
}

#[derive(Clone, Copy)]
pub(crate) struct PaneSplitHandle {
    pub(crate) id: u64,
    pub(crate) axis: SplitAxis,
    pub(crate) bounds: egui::Rect,
    pub(crate) hit_rect: egui::Rect,
}

#[derive(Clone, Copy)]
pub(crate) struct TabDrop {
    pub(crate) target: PaneId,
    pub(crate) zone: DropZone,
    pub(crate) preview: egui::Rect,
}

impl Default for PaneLayout {
    fn default() -> Self {
        Self {
            root: PaneNode::Leaf(PaneId(0)),
            next_id: 1,
            next_split_id: 0,
        }
    }
}

impl PaneLayout {
    pub(crate) fn split(&mut self, target: PaneId, zone: DropZone) -> Option<PaneId> {
        let new = PaneId(self.next_id);
        if self.root.split(target, new, zone, self.next_split_id) {
            self.next_id += 1;
            self.next_split_id += 1;
            Some(new)
        } else {
            None
        }
    }

    pub(crate) fn insert_at_split(&mut self, target: u64) -> Option<PaneId> {
        let new = PaneId(self.next_id);
        if self.root.insert_at_split(target, new, self.next_split_id) {
            self.next_id += 1;
            self.next_split_id += 1;
            Some(new)
        } else {
            None
        }
    }

    pub(crate) fn rects(&self, available: egui::Rect) -> Vec<(PaneId, egui::Rect)> {
        let mut rects = Vec::new();
        self.root.append_rects(available, &mut rects);
        rects
    }

    fn panes(&self) -> Vec<PaneId> {
        self.rects(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::Vec2::splat(1.0),
        ))
        .into_iter()
        .map(|(pane, _)| pane)
        .collect()
    }

    pub(crate) fn split_handles(&self, available: egui::Rect) -> Vec<PaneSplitHandle> {
        let mut handles = Vec::new();
        self.root.append_split_handles(available, &mut handles);
        handles
    }

    pub(crate) fn resize(&mut self, id: u64, bounds: egui::Rect, pointer: egui::Pos2) -> bool {
        self.root.resize(id, bounds, pointer)
    }

    pub(crate) fn resize_adjacent(
        &mut self,
        id: u64,
        available: egui::Rect,
        pointer: egui::Pos2,
    ) -> bool {
        let handles = self.split_handles(available);
        let Some(target) = handles.iter().find(|handle| handle.id == id) else {
            return false;
        };
        let preserved = handles
            .iter()
            .filter(|handle| handle.id != id && handle.axis == target.axis)
            .map(|handle| (handle.id, handle.hit_rect.center()))
            .collect::<Vec<_>>();
        if !self.resize(id, target.bounds, pointer) {
            return false;
        }
        for (preserved_id, center) in preserved {
            if let Some(handle) = self
                .split_handles(available)
                .into_iter()
                .find(|handle| handle.id == preserved_id)
            {
                self.resize(preserved_id, handle.bounds, center);
            }
        }
        true
    }

    pub(crate) fn remove(&mut self, target: PaneId) -> bool {
        if self.root.leaf_count() == 1 || !self.root.contains(target) {
            return false;
        }
        let root = std::mem::replace(&mut self.root, PaneNode::Leaf(target));
        self.root = root
            .without(target)
            .expect("another pane remains after removing a split leaf");
        true
    }
}

pub(crate) fn resize_dragged_pane_handle(
    ctx: &egui::Context,
    layout: &mut PaneLayout,
    available: egui::Rect,
    id_salt: &'static str,
    resize_adjacent: bool,
) -> Vec<PaneSplitHandle> {
    if ctx.input(|input| input.pointer.primary_down())
        && let Some(pointer) = ctx.pointer_interact_pos()
    {
        for handle in layout.split_handles(available) {
            if !ctx.is_being_dragged(Id::new((id_salt, handle.id))) {
                continue;
            }
            if resize_adjacent {
                layout.resize_adjacent(handle.id, available, pointer);
            } else {
                layout.resize(handle.id, handle.bounds, pointer);
            }
        }
    }
    layout.split_handles(available)
}

pub(crate) fn paint_pane_resize_handles(
    ui: &mut egui::Ui,
    handles: &[PaneSplitHandle],
    id_salt: &'static str,
) {
    for handle in handles {
        let response = ui.interact(
            handle.hit_rect,
            Id::new((id_salt, handle.id)),
            Sense::drag(),
        );
        let active = response.hovered() || response.dragged();
        if active {
            ui.ctx().set_cursor_icon(match handle.axis {
                SplitAxis::Horizontal => CursorIcon::ResizeVertical,
                SplitAxis::Vertical => CursorIcon::ResizeHorizontal,
            });
        }
        let center = handle.hit_rect.center();
        let line = match handle.axis {
            SplitAxis::Horizontal => [
                egui::pos2(handle.hit_rect.left(), center.y),
                egui::pos2(handle.hit_rect.right(), center.y),
            ],
            SplitAxis::Vertical => [
                egui::pos2(center.x, handle.hit_rect.top()),
                egui::pos2(center.x, handle.hit_rect.bottom()),
            ],
        };
        ui.painter()
            .line_segment(line, resize_divider_stroke(ui.ctx(), active));
    }
}

impl PaneNode {
    fn split(&mut self, target: PaneId, new: PaneId, zone: DropZone, split_id: u64) -> bool {
        match self {
            Self::Leaf(id) if *id == target && zone != DropZone::Center => {
                let existing = Self::Leaf(*id);
                let added = Self::Leaf(new);
                let (axis, first, second) = match zone {
                    DropZone::Left => (SplitAxis::Vertical, added, existing),
                    DropZone::Right => (SplitAxis::Vertical, existing, added),
                    DropZone::Top => (SplitAxis::Horizontal, added, existing),
                    DropZone::Bottom => (SplitAxis::Horizontal, existing, added),
                    DropZone::Center => return false,
                };
                *self = Self::Split {
                    id: split_id,
                    axis,
                    fraction: 0.5,
                    first: Box::new(first),
                    second: Box::new(second),
                };
                true
            }
            Self::Split { first, second, .. } => {
                first.split(target, new, zone, split_id)
                    || second.split(target, new, zone, split_id)
            }
            Self::Leaf(_) => false,
        }
    }

    fn insert_at_split(&mut self, target: u64, new: PaneId, split_id: u64) -> bool {
        match self {
            Self::Split { id, .. } if *id == target => {
                let Self::Split {
                    id,
                    axis,
                    fraction,
                    first,
                    second,
                } = std::mem::replace(self, Self::Leaf(new))
                else {
                    unreachable!()
                };
                let first_fraction = fraction * 2.0 / 3.0;
                let middle_fraction = (1.0 / 3.0) / (1.0 - first_fraction);
                *self = Self::Split {
                    id,
                    axis,
                    fraction: first_fraction,
                    first,
                    second: Box::new(Self::Split {
                        id: split_id,
                        axis,
                        fraction: middle_fraction,
                        first: Box::new(Self::Leaf(new)),
                        second,
                    }),
                };
                true
            }
            Self::Split { first, second, .. } => {
                first.insert_at_split(target, new, split_id)
                    || second.insert_at_split(target, new, split_id)
            }
            Self::Leaf(_) => false,
        }
    }

    fn append_rects(&self, available: egui::Rect, rects: &mut Vec<(PaneId, egui::Rect)>) {
        match self {
            Self::Leaf(id) => rects.push((*id, available)),
            Self::Split {
                axis,
                fraction,
                first,
                second,
                ..
            } => {
                let fraction = Self::clamped_fraction(available, *axis, *fraction, first, second);
                let (first_rect, second_rect) = match axis {
                    SplitAxis::Horizontal => {
                        let middle = available.top() + available.height() * fraction;
                        (available.with_max_y(middle), available.with_min_y(middle))
                    }
                    SplitAxis::Vertical => {
                        let middle = available.left() + available.width() * fraction;
                        (available.with_max_x(middle), available.with_min_x(middle))
                    }
                };
                first.append_rects(first_rect, rects);
                second.append_rects(second_rect, rects);
            }
        }
    }

    fn append_split_handles(&self, available: egui::Rect, handles: &mut Vec<PaneSplitHandle>) {
        let Self::Split {
            id,
            axis,
            fraction,
            first,
            second,
        } = self
        else {
            return;
        };
        let fraction = Self::clamped_fraction(available, *axis, *fraction, first, second);
        let (first_rect, second_rect, hit_rect) = match axis {
            SplitAxis::Horizontal => {
                let middle = available.top() + available.height() * fraction;
                (
                    available.with_max_y(middle),
                    available.with_min_y(middle),
                    egui::Rect::from_center_size(
                        egui::pos2(available.center().x, middle),
                        egui::vec2(available.width(), PANE_DIVIDER_HIT_WIDTH),
                    ),
                )
            }
            SplitAxis::Vertical => {
                let middle = available.left() + available.width() * fraction;
                (
                    available.with_max_x(middle),
                    available.with_min_x(middle),
                    egui::Rect::from_center_size(
                        egui::pos2(middle, available.center().y),
                        egui::vec2(PANE_DIVIDER_HIT_WIDTH, available.height()),
                    ),
                )
            }
        };
        handles.push(PaneSplitHandle {
            id: *id,
            axis: *axis,
            bounds: available,
            hit_rect,
        });
        first.append_split_handles(first_rect, handles);
        second.append_split_handles(second_rect, handles);
    }

    fn resize(&mut self, target: u64, bounds: egui::Rect, pointer: egui::Pos2) -> bool {
        match self {
            Self::Split {
                id,
                axis,
                fraction,
                first,
                second,
            } if *id == target => {
                let extent = match axis {
                    SplitAxis::Horizontal => bounds.height(),
                    SplitAxis::Vertical => bounds.width(),
                };
                if extent <= 0.0 {
                    return false;
                }
                let requested = match axis {
                    SplitAxis::Horizontal => (pointer.y - bounds.top()) / extent,
                    SplitAxis::Vertical => (pointer.x - bounds.left()) / extent,
                };
                *fraction = Self::clamped_fraction(bounds, *axis, requested, first, second);
                true
            }
            Self::Split { first, second, .. } => {
                first.resize(target, bounds, pointer) || second.resize(target, bounds, pointer)
            }
            Self::Leaf(_) => false,
        }
    }

    fn clamped_fraction(
        available: egui::Rect,
        axis: SplitAxis,
        fraction: f32,
        first: &Self,
        second: &Self,
    ) -> f32 {
        let extent = match axis {
            SplitAxis::Horizontal => available.height(),
            SplitAxis::Vertical => available.width(),
        };
        let first_min = first.minimum_extent(axis);
        let second_min = second.minimum_extent(axis);
        if extent <= first_min + second_min {
            return first_min / (first_min + second_min);
        }
        fraction.clamp(first_min / extent, 1.0 - second_min / extent)
    }

    fn minimum_extent(&self, axis: SplitAxis) -> f32 {
        match self {
            Self::Leaf(_) => match axis {
                SplitAxis::Horizontal => MIN_EDITOR_PANE_HEIGHT,
                SplitAxis::Vertical => MIN_EDITOR_PANE_WIDTH,
            },
            Self::Split {
                axis: split_axis,
                first,
                second,
                ..
            } if *split_axis == axis => first.minimum_extent(axis) + second.minimum_extent(axis),
            Self::Split { first, second, .. } => {
                first.minimum_extent(axis).max(second.minimum_extent(axis))
            }
        }
    }

    fn contains(&self, target: PaneId) -> bool {
        match self {
            Self::Leaf(id) => *id == target,
            Self::Split { first, second, .. } => first.contains(target) || second.contains(target),
        }
    }

    fn leaf_count(&self) -> usize {
        match self {
            Self::Leaf(_) => 1,
            Self::Split { first, second, .. } => first.leaf_count() + second.leaf_count(),
        }
    }

    fn without(self, target: PaneId) -> Option<Self> {
        match self {
            Self::Leaf(id) => (id != target).then_some(Self::Leaf(id)),
            Self::Split {
                id,
                axis,
                fraction,
                first,
                second,
            } => match (first.without(target), second.without(target)) {
                (Some(first), Some(second)) => Some(Self::Split {
                    id,
                    axis,
                    fraction,
                    first: Box::new(first),
                    second: Box::new(second),
                }),
                (Some(node), None) | (None, Some(node)) => Some(node),
                (None, None) => None,
            },
        }
    }
}

fn tab_drop_edges(rect: egui::Rect, pointer: egui::Pos2) -> [(f32, DropZone); 4] {
    let x = ((pointer.x - rect.left()) / rect.width().max(1.0)).clamp(0.0, 1.0);
    let y = ((pointer.y - rect.top()) / rect.height().max(1.0)).clamp(0.0, 1.0);
    [
        (x, DropZone::Left),
        (1.0 - x, DropZone::Right),
        (y, DropZone::Top),
        (1.0 - y, DropZone::Bottom),
    ]
}

fn allowed_tab_drop_zone(rect: egui::Rect, pointer: egui::Pos2) -> DropZone {
    tab_drop_zone(rect, pointer, 0.22)
}

pub(crate) fn stable_tab_drop_zone(
    rect: egui::Rect,
    pointer: egui::Pos2,
    previous: Option<DropZone>,
) -> DropZone {
    if let Some(previous) = previous.filter(|zone| *zone != DropZone::Center)
        && tab_drop_edges(rect, pointer)
            .into_iter()
            .any(|(distance, zone)| zone == previous && distance <= 0.32 && can_split(rect, zone))
    {
        return previous;
    }
    allowed_tab_drop_zone(rect, pointer)
}

fn tab_drop_zone(rect: egui::Rect, pointer: egui::Pos2, threshold: f32) -> DropZone {
    tab_drop_edges(rect, pointer)
        .into_iter()
        .filter(|(distance, zone)| *distance <= threshold && can_split(rect, *zone))
        .min_by(|(left, _), (right, _)| left.total_cmp(right))
        .map_or(DropZone::Center, |(_, zone)| zone)
}

fn can_split(rect: egui::Rect, zone: DropZone) -> bool {
    let can_split_columns = rect.width() >= MIN_EDITOR_PANE_WIDTH * 2.0;
    let can_split_rows = rect.height() >= MIN_EDITOR_PANE_HEIGHT * 2.0;
    match zone {
        DropZone::Left | DropZone::Right => can_split_columns,
        DropZone::Top | DropZone::Bottom => can_split_rows,
        DropZone::Center => false,
    }
}

pub(crate) fn tab_drop_preview(rect: egui::Rect, zone: DropZone) -> egui::Rect {
    match zone {
        DropZone::Center => rect,
        DropZone::Left => rect.with_max_x(rect.center().x),
        DropZone::Right => rect.with_min_x(rect.center().x),
        DropZone::Top => rect.with_max_y(rect.center().y),
        DropZone::Bottom => rect.with_min_y(rect.center().y),
    }
}

/// Measured with the active tab's face so a tab does not resize when it is
/// selected, which would shift every label to its right.
fn tab_width(ui: &egui::Ui, label: &str) -> f32 {
    let text = ui
        .painter()
        .layout_no_wrap(
            label.to_owned(),
            theme::typography::strong(),
            theme::text().primary,
        )
        .size()
        .x;
    (theme::space::MEDIUM + TAB_DOT + text + theme::space::SMALL + TAB_CLOSE + theme::space::SMALL)
        .clamp(TAB_MIN_WIDTH, TAB_MAX_WIDTH)
}

fn drag_label(path: &Path) -> Cow<'_, str> {
    path.file_name()
        .unwrap_or(path.as_os_str())
        .to_string_lossy()
}

fn draw_dragged_pane_preview(painter: &egui::Painter, rect: egui::Rect, path: Option<&Path>) {
    let painter = painter.with_clip_rect(rect);
    let inset = 2.0_f32.min(rect.width().min(rect.height()).max(0.0) * 0.5);
    let rect = rect.shrink(inset);
    let header = rect.with_max_y((rect.top() + PANE_TAB_HEIGHT).min(rect.bottom()));
    painter.rect_filled(
        rect,
        theme::corner(theme::radius::ROW),
        editor_background().gamma_multiply(0.70),
    );
    painter.rect_filled(
        header,
        theme::corner(theme::radius::ROW),
        theme::surface().chrome.gamma_multiply(0.77),
    );
    painter.rect_stroke(
        rect,
        theme::corner(theme::radius::ROW),
        egui::Stroke::new(theme::stroke::FOCUS, theme::accent().gamma_multiply(0.75)),
        egui::StrokeKind::Inside,
    );
    if let Some(path) = path {
        painter.text(
            egui::pos2(header.left() + theme::space::MEDIUM, header.center().y),
            Align2::LEFT_CENTER,
            drag_label(path),
            theme::typography::small(),
            theme::text().primary.gamma_multiply(0.75),
        );
    }
}

pub(crate) fn draw_tab_drag_ghost(ctx: &egui::Context, label: &str) {
    let Some(pointer) = ctx.pointer_hover_pos() else {
        return;
    };
    let screen = ctx.content_rect();
    let painter = ctx.layer_painter(egui::LayerId::new(
        egui::Order::Tooltip,
        Id::new("tab_drag_ghost"),
    ));
    let galley = painter.layout_no_wrap(
        label.to_owned(),
        theme::typography::small(),
        theme::text().primary,
    );
    let size = egui::vec2(
        (galley.size().x + 28.0)
            .clamp(100.0, 220.0)
            .min(screen.width()),
        30.0_f32.min(screen.height()),
    );
    let offset = egui::vec2(14.0, 14.0);
    let min = egui::pos2(
        (pointer.x + offset.x).clamp(screen.left(), (screen.right() - size.x).max(screen.left())),
        (pointer.y + offset.y).clamp(screen.top(), (screen.bottom() - size.y).max(screen.top())),
    );
    let rect = egui::Rect::from_min_size(min, size);
    crate::renderer::mark_retained(
        &painter,
        rect,
        TAB_DRAG_GHOST_PAINT_KEY,
        u64::from(rect.left().to_bits())
            ^ u64::from(rect.top().to_bits()).rotate_left(16)
            ^ u64::from(rect.width().to_bits()).rotate_left(32)
            ^ u64::from(rect.height().to_bits()).rotate_left(48),
    );
    painter.add(theme::shadow::popover().as_shape(rect, theme::corner(theme::radius::CONTROL)));
    painter.rect_filled(
        rect,
        theme::corner(theme::radius::CONTROL),
        theme::surface().raised.gamma_multiply(0.88),
    );
    painter.rect_stroke(
        rect,
        theme::corner(theme::radius::CONTROL),
        theme::border::strong(),
        egui::StrokeKind::Inside,
    );
    painter.rect_filled(
        egui::Rect::from_min_max(
            rect.left_top(),
            egui::pos2(rect.left() + theme::space::HAIR + 1.0, rect.bottom()),
        ),
        theme::corner(theme::radius::CONTROL),
        theme::accent(),
    );
    let clip_inset = 6.0_f32.min(rect.width().min(rect.height()).max(0.0) * 0.5);
    painter.with_clip_rect(rect.shrink(clip_inset)).galley(
        egui::pos2(rect.left() + 14.0, rect.center().y - galley.size().y * 0.5),
        galley,
        theme::text().primary,
    );
}

fn titlebar_drag_action(
    ui: &mut egui::Ui,
    rect: egui::Rect,
    region: impl Hash + std::fmt::Debug,
) -> Option<WindowAction> {
    if rect.width() <= 0.0 {
        return None;
    }
    let response = ui.interact(
        rect,
        Id::new(("titlebar_drag", region)),
        Sense::click_and_drag(),
    );
    if response.drag_started() {
        Some(WindowAction::Drag)
    } else if response.double_clicked() {
        Some(WindowAction::ToggleMaximize)
    } else {
        None
    }
}

#[cfg(target_os = "macos")]
fn macos_titlebar_controls(
    ui: &mut egui::Ui,
    rect: egui::Rect,
    id: &'static str,
) -> Option<WindowAction> {
    let pointer = ui.ctx().pointer_hover_pos();
    let button_centers = [17.0, 37.0, 57.0].map(|x| egui::pos2(rect.left() + x, rect.center().y));
    let hovered = button_centers
        .iter()
        .position(|center| pointer.is_some_and(|pointer| pointer.distance(*center) <= 10.0));
    let focused = ui.input(|input| input.focused);
    let actions = [
        (WindowAction::Close, theme::traffic::CLOSE, Icon::Close),
        (
            WindowAction::Minimize,
            theme::traffic::MINIMIZE,
            Icon::Minus,
        ),
        (
            WindowAction::ToggleMaximize,
            theme::traffic::ZOOM,
            Icon::Plus,
        ),
    ];
    let mut selected = None;
    for (index, ((action, color, glyph), center)) in
        actions.into_iter().zip(button_centers).enumerate()
    {
        let button = egui::Rect::from_center_size(center, egui::vec2(18.0, 24.0));
        if ui
            .interact(
                button,
                Id::new((id, "titlebar_button", index)),
                Sense::click(),
            )
            .clicked()
        {
            selected = Some(action);
        }
        let fill = if focused {
            color
        } else {
            theme::traffic::unfocused()
        };
        ui.painter().circle_filled(center, 6.0, fill);
        if hovered == Some(index) {
            icons::paint(
                ui.painter(),
                glyph,
                egui::Rect::from_center_size(center, egui::Vec2::splat(icons::GRID * 0.5)),
                theme::traffic::glyph(),
            );
        }
    }
    selected
}

fn agent_composer_height(text_height: f32, row_height: f32, sidebar_height: f32) -> f32 {
    let max_height =
        AGENT_COMPOSER_MAX_HEIGHT.min((sidebar_height * 0.45).max(AGENT_COMPOSER_HEIGHT));
    (AGENT_COMPOSER_HEIGHT + (text_height - row_height * 3.0).max(0.0)).min(max_height)
}

fn agentic_empty_state_top_padding(available_height: f32) -> f32 {
    ((available_height - AGENTIC_EMPTY_STATE_HEIGHT) * 0.5).max(0.0)
}

fn split_agent_sidebar(
    rect: egui::Rect,
    composer_height: f32,
) -> (egui::Rect, egui::Rect, egui::Rect) {
    let header = rect.with_max_y((rect.top() + AGENT_HEADER_HEIGHT).min(rect.bottom()));
    let composer = rect.with_min_y(
        (rect.bottom() - composer_height)
            .max(header.bottom())
            .min(rect.bottom()),
    );
    let transcript = egui::Rect::from_min_max(header.left_bottom(), composer.right_top());
    (header, transcript, composer)
}

fn agent_toggle_rect(header: egui::Rect) -> egui::Rect {
    #[cfg(target_os = "macos")]
    let controls_right = header.right();
    #[cfg(not(target_os = "macos"))]
    let controls_right = header.right() - 3.0 * 46.0;
    egui::Rect::from_center_size(
        egui::pos2(controls_right - 17.0, header.center().y),
        egui::vec2(34.0, header.height()),
    )
}

fn file_tree_toggle_rect(titlebar: egui::Rect, _editor_header: egui::Rect) -> egui::Rect {
    #[cfg(target_os = "macos")]
    let controls_right = titlebar.left() + 72.0;
    #[cfg(not(target_os = "macos"))]
    let controls_right = _editor_header.left();
    egui::Rect::from_center_size(
        egui::pos2(controls_right + 17.0, titlebar.center().y),
        egui::vec2(34.0, titlebar.height()),
    )
}

fn terminal_toggle_rect(file_tree_button: egui::Rect) -> egui::Rect {
    file_tree_button.translate(egui::vec2(file_tree_button.width(), 0.0))
}

fn settings_toggle_rect(terminal_button: egui::Rect) -> egui::Rect {
    terminal_button.translate(egui::vec2(terminal_button.width(), 0.0))
}

fn agentic_toggle_rect(file_tree_button: egui::Rect, sidebar_right: Option<f32>) -> egui::Rect {
    let right = sidebar_right
        .map(|right| {
            if file_tree_button.left() >= right {
                right
            } else {
                right.max(file_tree_button.right() + AGENTIC_MODE_TOGGLE_WIDTH)
            }
        })
        .unwrap_or(file_tree_button.right() + AGENTIC_MODE_TOGGLE_WIDTH);
    egui::Rect::from_center_size(
        egui::pos2(
            right - AGENTIC_MODE_TOGGLE_WIDTH * 0.5,
            file_tree_button.center().y,
        ),
        egui::vec2(AGENTIC_MODE_TOGGLE_WIDTH, file_tree_button.height()),
    )
}

fn draw_sidebar_toggle_icon(
    ui: &mut egui::Ui,
    button: egui::Rect,
    response: &egui::Response,
    open: bool,
    panel_on_right: bool,
) -> egui::Pos2 {
    let icon_center = button.center();
    let icon = egui::Rect::from_center_size(icon_center, egui::vec2(16.0, 13.0));
    let icon_color = if response.hovered() || open {
        theme::text().primary
    } else {
        theme::text().muted
    };
    ui.painter().rect_stroke(
        icon,
        2.0,
        egui::Stroke::new(1.2, icon_color),
        egui::StrokeKind::Inside,
    );
    let divider_x = if panel_on_right {
        icon.right() - 4.5
    } else {
        icon.left() + 4.5
    };
    ui.painter().vline(
        divider_x,
        icon.y_range(),
        egui::Stroke::new(1.2, icon_color),
    );
    if open {
        let selected = if panel_on_right {
            egui::Rect::from_min_max(egui::pos2(divider_x, icon.top()), icon.right_bottom())
        } else {
            egui::Rect::from_min_max(icon.left_top(), egui::pos2(divider_x, icon.bottom()))
        };
        ui.painter()
            .rect_filled(selected, 1.0, theme::state::selected());
    }
    icon_center
}

fn agent_new_session_rect(header: egui::Rect) -> egui::Rect {
    let toggle = agent_toggle_rect(header);
    egui::Rect::from_center_size(
        egui::pos2(toggle.center().x - 33.0, header.center().y),
        egui::vec2(32.0, 32.0),
    )
}

fn agent_sessions_rect(header: egui::Rect) -> egui::Rect {
    let new_session = agent_new_session_rect(header);
    egui::Rect::from_center_size(
        egui::pos2(new_session.center().x - 33.0, header.center().y),
        egui::vec2(32.0, 32.0),
    )
}

fn agent_search_rect(header: egui::Rect, agentic_mode: bool) -> egui::Rect {
    if agentic_mode {
        agent_toggle_rect(header)
    } else {
        agent_sessions_rect(header).translate(egui::vec2(-33.0, 0.0))
    }
}

/// Inset the composer so the prompt and footer share one rhythm: equal sides,
/// a little extra air under the toolbar so the selects don't sit on the edge.
fn agent_composer_content(composer: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(
            composer.left() + theme::space::MEDIUM,
            composer.top() + theme::space::MEDIUM,
        ),
        egui::pos2(
            composer.right() - theme::space::MEDIUM,
            composer.bottom() - (theme::space::LARGE - 5.0),
        ),
    )
}

fn agent_menu_rect(
    transcript: egui::Rect,
    anchor: egui::Rect,
    item_count: usize,
    row_height: f32,
    vertical_padding: f32,
) -> egui::Rect {
    let width = AGENT_MENU_WIDTH.min((transcript.width() - 12.0).max(1.0));
    let desired_height = 2.0 * vertical_padding + (item_count as f32 * row_height).min(280.0);
    let bottom = anchor.top() - 4.0;
    let height = desired_height.min((bottom - transcript.top() - 8.0).max(1.0));
    let left = anchor.left().clamp(
        transcript.left() + 6.0,
        (transcript.right() - width - 6.0).max(transcript.left() + 6.0),
    );
    egui::Rect::from_min_size(egui::pos2(left, bottom - height), egui::vec2(width, height))
}

fn agent_session_menu_rect(
    transcript: egui::Rect,
    anchor: egui::Rect,
    item_count: usize,
    row_height: f32,
    width: f32,
) -> egui::Rect {
    let width = width.min((transcript.width() - 12.0).max(1.0));
    let top = anchor.bottom() + 4.0;
    let height = (16.0 + item_count as f32 * row_height)
        .min(280.0)
        .min((transcript.bottom() - top - 8.0).max(1.0));
    let left = (anchor.right() - width).clamp(
        transcript.left() + 6.0,
        (transcript.right() - width - 6.0).max(transcript.left() + 6.0),
    );
    egui::Rect::from_min_size(egui::pos2(left, top), egui::vec2(width, height))
}

fn agent_provider_menu_rect(
    bounds: egui::Rect,
    anchor: egui::Rect,
    item_count: usize,
    row_height: f32,
) -> egui::Rect {
    let width = AGENT_PROVIDER_MENU_WIDTH.min((bounds.width() - 16.0).max(1.0));
    let top = anchor.bottom() + 6.0;
    let height = (16.0 + item_count as f32 * row_height)
        .min(280.0)
        .min((bounds.bottom() - top - 8.0).max(1.0));
    let left = anchor.left().clamp(
        bounds.left() + 8.0,
        (bounds.right() - width - 8.0).max(bounds.left() + 8.0),
    );
    egui::Rect::from_min_size(egui::pos2(left, top), egui::vec2(width, height))
}

fn slash_command_query(prompt: &str) -> Option<&str> {
    prompt
        .strip_prefix('/')
        .filter(|query| !query.chars().any(char::is_whitespace))
}

fn agent_mention_query(prompt: &str) -> Option<&str> {
    if prompt.chars().next_back().is_some_and(char::is_whitespace) {
        return None;
    }
    let token = prompt.split_whitespace().next_back()?;
    let query = token.strip_prefix('@')?;
    (token.len() == query.len() + 1).then_some(query)
}

fn remove_agent_mention(prompt: &mut String) {
    if agent_mention_query(prompt).is_some() {
        let start = prompt.rfind('@').unwrap_or(prompt.len());
        prompt.truncate(start);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct AgentMentionEntry {
    path: PathBuf,
    relative: String,
    is_dir: bool,
}

fn collect_agent_mentions(root: &Path) -> Vec<AgentMentionEntry> {
    let mut found = Vec::new();
    let mut directories = vec![root.to_path_buf()];
    while let Some(directory) = directories.pop() {
        let Ok(entries) = fs::read_dir(&directory) else {
            continue;
        };
        let mut entries = entries.filter_map(Result::ok).collect::<Vec<_>>();
        entries.sort_by_key(std::fs::DirEntry::file_name);
        for entry in entries {
            let Ok(file_type) = entry.file_type() else {
                continue;
            };
            if file_type.is_symlink() {
                continue;
            }
            let is_dir = file_type.is_dir();
            if is_dir && crate::search::ignored_directory(&entry.file_name().to_string_lossy()) {
                continue;
            }
            if !is_dir && !file_type.is_file() {
                continue;
            }
            let path = entry.path();
            let Ok(relative) = path.strip_prefix(root) else {
                continue;
            };
            found.push(AgentMentionEntry {
                path: path.clone(),
                relative: relative
                    .components()
                    .map(|component| component.as_os_str().to_string_lossy())
                    .collect::<Vec<_>>()
                    .join("/"),
                is_dir,
            });
            if is_dir {
                directories.push(path);
            }
        }
    }
    found
}

fn agent_mention_matches(entries: &[AgentMentionEntry], query: &str) -> Vec<AgentMentionEntry> {
    let query = query.to_ascii_lowercase();
    let mut matches = entries
        .iter()
        .filter_map(|entry| {
            let relative = entry.relative.to_ascii_lowercase();
            let name = entry
                .path
                .file_name()
                .unwrap_or(entry.path.as_os_str())
                .to_string_lossy()
                .to_ascii_lowercase();
            let score = if query.is_empty() || name == query {
                0
            } else if name.starts_with(&query) {
                1
            } else if name.contains(&query) {
                2
            } else if relative.contains(&query) {
                3
            } else {
                return None;
            };
            Some((score, entry.relative.len(), entry))
        })
        .collect::<Vec<_>>();
    matches.sort_by(|left, right| {
        (left.0, left.1, left.2.relative.as_str()).cmp(&(
            right.0,
            right.1,
            right.2.relative.as_str(),
        ))
    });
    matches
        .into_iter()
        .take(10)
        .map(|(_, _, entry)| entry.clone())
        .collect()
}

fn append_display_search_text(text: &mut String, content: &DisplayContent) {
    use std::fmt::Write as _;
    match content {
        DisplayContent::Image { mime_type, uri, .. } => {
            let _ = writeln!(text, "{mime_type}");
            if let Some(uri) = uri {
                let _ = writeln!(text, "{uri}");
            }
        }
        DisplayContent::Audio { mime_type, .. } => {
            let _ = writeln!(text, "{mime_type}");
        }
        DisplayContent::ResourceLink {
            name,
            title,
            uri,
            description,
            mime_type,
            ..
        } => {
            let _ = writeln!(text, "{name}\n{uri}");
            for value in [title, description, mime_type].into_iter().flatten() {
                let _ = writeln!(text, "{value}");
            }
        }
        DisplayContent::TextResource {
            uri,
            mime_type,
            text: content,
        } => {
            let _ = writeln!(text, "{uri}\n{content}");
            if let Some(mime_type) = mime_type {
                let _ = writeln!(text, "{mime_type}");
            }
        }
        DisplayContent::BlobResource { uri, mime_type, .. } => {
            let _ = writeln!(text, "{uri}");
            if let Some(mime_type) = mime_type {
                let _ = writeln!(text, "{mime_type}");
            }
        }
    }
}

fn agent_searchable_text(item: &TranscriptItem) -> Option<String> {
    use std::fmt::Write as _;
    let mut text = String::new();
    match item {
        TranscriptItem::Thought(_)
        | TranscriptItem::Content {
            role: ContentRole::Thought,
            ..
        } => return None,
        TranscriptItem::User(content)
        | TranscriptItem::Assistant(content)
        | TranscriptItem::Error(content) => text.push_str(content),
        TranscriptItem::Content { content, .. } => append_display_search_text(&mut text, content),
        TranscriptItem::Plan(items) => {
            for item in items {
                let _ = writeln!(text, "{} {}", item.status, item.content);
            }
        }
        TranscriptItem::Tool(tool) => {
            let title = tool.display_title();
            let _ = writeln!(text, "{title}");
            let action = title.split_whitespace().next();
            let title_includes_paths = action.is_some_and(|action| {
                action.eq_ignore_ascii_case("Read") || action.eq_ignore_ascii_case("Edit")
            });
            if !title_includes_paths {
                for path in &tool.paths {
                    let _ = writeln!(text, "{}", path.path.display());
                }
            }
            if let Some(detail) = &tool.detail {
                if detail.content.is_empty()
                    && let Some(value) = detail.output.as_ref().or(detail.input.as_ref())
                {
                    let _ = writeln!(text, "{value}");
                }
                for content in &detail.content {
                    match content {
                        ToolOutput::Text(content) => {
                            let _ = writeln!(text, "{content}");
                        }
                        ToolOutput::Content(content) => {
                            append_display_search_text(&mut text, content)
                        }
                        ToolOutput::Diff {
                            path,
                            old_text,
                            new_text,
                        } => {
                            let _ = writeln!(text, "{}", path.display());
                            for line in &build_agent_diff(old_text.as_deref(), new_text).lines {
                                let _ = writeln!(text, "{}", line.text);
                            }
                        }
                        ToolOutput::Terminal(id) => {
                            let _ = writeln!(text, "Terminal {id}");
                        }
                        ToolOutput::Todo {
                            id,
                            content,
                            status,
                        } => {
                            let _ = writeln!(text, "{status} {content} {id}");
                        }
                        ToolOutput::Task {
                            description,
                            prompt,
                            subagent_type,
                            model,
                            duration_ms,
                            ..
                        } => {
                            let _ = writeln!(text, "{description}\n{prompt}\n{subagent_type}");
                            if let Some(model) = model {
                                let _ = writeln!(text, "{model}");
                            }
                            if let Some(duration_ms) = duration_ms {
                                let _ = writeln!(text, "{}", agent_task_duration(*duration_ms));
                            }
                        }
                        ToolOutput::GeneratedImage {
                            description,
                            file_path,
                            reference_image_paths,
                        } => {
                            let _ = writeln!(text, "{description}");
                            if let Some(path) = file_path {
                                let _ = writeln!(text, "{}", path.display());
                            }
                            for path in reference_image_paths {
                                let _ = writeln!(text, "{}", path.display());
                            }
                        }
                    }
                }
            }
        }
        TranscriptItem::Permission(card) => {
            let _ = writeln!(text, "{}", card.action);
            for option in &card.options {
                let _ = writeln!(text, "{} {}", option.name, option.kind);
            }
        }
        TranscriptItem::Interaction(card) => match &card.request.kind {
            InteractionKind::Questions { title, questions } => {
                let _ = writeln!(text, "{title}");
                for question in questions {
                    let _ = writeln!(text, "{}", question.prompt);
                    for option in &question.options {
                        let _ = writeln!(text, "{}", option.label);
                    }
                }
            }
            InteractionKind::Plan(plan) => {
                for value in [&plan.name, &plan.overview].into_iter().flatten() {
                    let _ = writeln!(text, "{value}");
                }
                let _ = writeln!(text, "{}", plan.plan);
                for item in plan
                    .todos
                    .iter()
                    .chain(plan.phases.iter().flat_map(|phase| phase.todos.iter()))
                {
                    let _ = writeln!(text, "{} {}", item.status, item.content);
                }
                for phase in &plan.phases {
                    let _ = writeln!(text, "{}", phase.name);
                }
            }
        },
        TranscriptItem::Truncated => text.push_str("Earlier output was truncated."),
    }
    Some(text)
}

fn agent_search_matches(
    transcript: &std::collections::VecDeque<TranscriptItem>,
    changed_paths: &HashMap<PathBuf, FileChange>,
    query: &str,
) -> Vec<usize> {
    if query.is_empty() {
        return Vec::new();
    }
    let mut matches = Vec::new();
    for (index, item) in transcript.iter().enumerate() {
        let count = agent_searchable_text(item)
            .map(|text| match_spans(&text, query).len())
            .unwrap_or(0);
        matches.extend(std::iter::repeat_n(index, count));
    }
    let changed_index = transcript.len();
    let mut paths = changed_paths.keys().collect::<Vec<_>>();
    paths.sort();
    for path in paths {
        let count = match_spans(&path.display().to_string(), query).len();
        matches.extend(std::iter::repeat_n(changed_index, count));
    }
    matches
}

fn paint_agent_search_item(ui: &mut egui::Ui, top: f32, selected: bool, scroll: bool) -> bool {
    let rect = egui::Rect::from_min_max(
        egui::pos2(ui.min_rect().left(), top),
        egui::pos2(ui.min_rect().right(), ui.cursor().top()),
    );
    if selected && scroll {
        ui.scroll_to_rect(rect, Some(Align::Center));
        true
    } else {
        false
    }
}

fn command_matches(name: &str, query: &str) -> bool {
    name.to_ascii_lowercase()
        .starts_with(&query.to_ascii_lowercase())
}

fn run_everything_state(commands: &[crate::agent::controller::CommandChoice]) -> Option<bool> {
    let command = commands
        .iter()
        .find(|command| matches!(command.name.as_str(), "run-everything" | "auto-run"))?;
    let description = command.description.to_ascii_lowercase();
    (!description.contains("disabled by admin") && !description.contains("checking"))
        .then(|| description.contains("currently enabled"))
}

fn provider_selector_visible(available: &[crate::agent::provider::ProviderId]) -> bool {
    available.len() >= 2
}

